/// A quantity that can be plotted.
#[derive(Clone, Debug, PartialEq)]
pub enum Var {
    Node(usize),
    Current { comp: usize },
}

pub fn var_name(c: &Circuit, v: &Var) -> String {
    match v {
        Var::Node(n) => format!("V({})", n),
        Var::Current { comp } => format!("I({})", c.components.get(*comp).map(|x| x.refdes.as_str()).unwrap_or("?")),
    }
}

/// All plottable variables: every non-ground net, and currents through sources and passive parts.
pub fn all_vars(c: &Circuit, nl: &Netlist) -> Vec<Var> {
    let mut v: Vec<Var> = (1..nl.n_nets).map(Var::Node).collect();
    for (i, comp) in c.components.iter().enumerate() {
        match comp.kind {
            Kind::Resistor
            | Kind::Capacitor
            | Kind::Inductor
            | Kind::DcVoltage
            | Kind::AcVoltage
            | Kind::Diode
            | Kind::Zener
            | Kind::Led
            | Kind::Lamp
            | Kind::Ammeter
            | Kind::Switch => v.push(Var::Current { comp: i }),
            _ => {}
        }
    }
    v
}

pub fn eval_var(sim: &Sim, v: &Var) -> f64 {
    match v {
        Var::Node(n) => sim.v(*n),
        Var::Current { comp } => sim.comp_current(*comp),
    }
}

pub struct OpResult {
    pub rows: Vec<(String, f64, &'static str)>,
}

pub fn run_dc_op(c: &Circuit) -> Result<OpResult, String> {
    let mut sim = Sim::new(c)?;
    sim.dc_op()?;
    let mut rows = Vec::new();
    for v in all_vars(c, &sim.nl) {
        let unit = if matches!(v, Var::Node(_)) { "V" } else { "A" };
        rows.push((var_name(c, &v), eval_var(&sim, &v), unit));
    }
    Ok(OpResult { rows })
}

pub struct Series {
    pub name: String,
    pub pts: Vec<[f64; 2]>,
}

pub fn run_transient(c: &Circuit, tstop: f64, tstep: f64, use_op: bool, vars: &[Var]) -> Result<Vec<Series>, String> {
    let mut sim = Sim::new(c)?;
    if use_op {
        sim.dc_op()?;
    }
    let mut out: Vec<Series> = vars.iter().map(|v| Series { name: var_name(c, v), pts: Vec::new() }).collect();
    let steps = ((tstop / tstep).ceil() as usize).clamp(1, 2_000_000);
    let keep_every = (steps / 20_000).max(1);
    for (s, v) in out.iter_mut().zip(vars) {
        s.pts.push([0.0, eval_var(&sim, v)]);
    }
    for k in 1..=steps {
        sim.step(tstep)?;
        if k % keep_every == 0 || k == steps {
            for (s, v) in out.iter_mut().zip(vars) {
                s.pts.push([sim.t, eval_var(&sim, v)]);
            }
        }
    }
    Ok(out)
}

pub struct AcSeries {
    pub name: String,
    pub mag: Vec<[f64; 2]>,
    pub phase: Vec<[f64; 2]>,
}

pub fn run_ac(c: &Circuit, fstart: f64, fstop: f64, ppd: usize, vars: &[Var]) -> Result<Vec<AcSeries>, String> {
    let mut sim = Sim::new(c)?;
    sim.dc_op()?;
    let has_ac = sim.els.iter().any(|e| match &e.k {
        EK::V(s) | EK::I(s) => s.ac_mag() != 0.0,
        _ => false,
    });
    if !has_ac {
        return Err("AC sweep needs an AC source (AC voltage source or function generator).".into());
    }
    let mut out: Vec<AcSeries> = vars
        .iter()
        .map(|v| AcSeries { name: var_name(c, v), mag: vec![], phase: vec![] })
        .collect();
    let (l0, l1) = (fstart.max(1e-3).log10(), fstop.max(fstart * 1.0001).log10());
    let npts = (((l1 - l0) * ppd as f64).ceil() as usize).max(2);
    for i in 0..=npts {
        let lf = l0 + (l1 - l0) * i as f64 / npts as f64;
        let f = 10f64.powf(lf);
        let sol = sim.ac_point(f).ok_or("AC equations could not be solved.")?;
        for (s, v) in out.iter_mut().zip(vars) {
            let z = match v {
                Var::Node(n) => {
                    if *n == 0 {
                        Cx::default()
                    } else {
                        sol[n - 1]
                    }
                }
                Var::Current { comp } => {
                    // current through first element of the component
                    let mut z = Cx::default();
                    for e in sim.els.iter() {
                        if e.comp == *comp && e.role == 0 {
                            let va = if e.a == 0 { Cx::default() } else { sol[e.a - 1] };
                            let vb = if e.b == 0 { Cx::default() } else { sol[e.b - 1] };
                            let vab = va.sub(vb);
                            let w = 2.0 * std::f64::consts::PI * f;
                            z = match e.k {
                                EK::R(r) => Cx::new(vab.re / r, vab.im / r),
                                EK::C(cap) => vab.mul(Cx::new(0.0, w * cap)),
                                EK::L(_) | EK::V(_) => sol[sim.nn + e.branch.unwrap()],
                                _ => Cx::default(),
                            };
                            break;
                        }
                    }
                    z
                }
            };
            let m = z.abs();
            s.mag.push([lf, 20.0 * m.max(1e-30).log10()]);
            s.phase.push([lf, z.arg().to_degrees()]);
        }
    }
    Ok(out)
}

pub fn run_dc_sweep(c: &Circuit, comp: usize, start: f64, stop: f64, incr: f64, vars: &[Var]) -> Result<Vec<Series>, String> {
    let mut sim = Sim::new(c)?;
    match c.components.get(comp).map(|k| k.kind) {
        Some(Kind::DcVoltage) | Some(Kind::DcCurrent) => {}
        _ => return Err("Choose a DC voltage or DC current source to sweep.".into()),
    }
    if incr <= 0.0 {
        return Err("The increment must be greater than zero.".into());
    }
    let mut out: Vec<Series> = vars.iter().map(|v| Series { name: var_name(c, v), pts: Vec::new() }).collect();
    let n = (((stop - start) / incr).abs().floor() as usize).min(100_000);
    let dir = if stop >= start { 1.0 } else { -1.0 };
    for i in 0..=n {
        let val = start + dir * incr * i as f64;
        sim.set_dc_source(comp, val);
        sim.dc_op()?;
        for (s, v) in out.iter_mut().zip(vars) {
            s.pts.push([val, eval_var(&sim, v)]);
        }
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn divider() -> Circuit {
        let mut c = Circuit::default();
        // V1 vertical at (0,0): + at (0,-3), - at (0,3)
        c.add(Kind::DcVoltage, GP::new(0, 0), 0);
        c.components[0].params.value = 10.0;
        // R1 horizontal at (5,-3): pins (2,-3) (8,-3)
        c.add(Kind::Resistor, GP::new(5, -3), 0);
        // R2 vertical at (8,0): rot 1 -> pins (8,-3) (8,3)
        c.add(Kind::Resistor, GP::new(8, 0), 1);
        c.add(Kind::Ground, GP::new(0, 3), 0);
        c.add_wire(vec![GP::new(0, -3), GP::new(2, -3)]);
        c.add_wire(vec![GP::new(0, 3), GP::new(8, 3)]);
        c
    }

    #[test]
    fn divider_op() {
        let c = divider();
        let mut s = Sim::new(&c).unwrap();
        s.dc_op().unwrap();
        let n_mid = s.nl.comp_nets[1][1];
        assert!((s.v(n_mid) - 5.0).abs() < 1e-6, "{}", s.v(n_mid));
    }

    #[test]
    fn diode_forward() {
        let mut c = divider();
        c.components[2].kind = Kind::Diode;
        c.components[2].params = Kind::Diode.default_params();
        let mut s = Sim::new(&c).unwrap();
        s.dc_op().unwrap();
        let n_mid = s.nl.comp_nets[1][1];
        let v = s.v(n_mid);
        assert!(v > 0.5 && v < 0.9, "{}", v);
    }

    #[test]
    fn rc_charge() {
        let mut c = divider();
        c.components[2].kind = Kind::Capacitor;
        c.components[2].params = Kind::Capacitor.default_params(); // 1uF, R=1k => tau 1ms
        let mut s = Sim::new(&c).unwrap();
        for _ in 0..1000 {
            s.step(1e-6).unwrap();
        }
        let n_mid = s.nl.comp_nets[1][1];
        let v = s.v(n_mid);
        assert!((v - 10.0 * (1.0 - (-1.0f64).exp())).abs() < 0.02, "{}", v);
    }
}

//! Drawing schematic symbols with egui's painter.

use crate::model::*;
use egui::{pos2, vec2, Align2, Color32, FontId, Painter, Pos2, Rect, Shape, Stroke};

pub const INK: Color32 = Color32::from_rgb(28, 32, 110);
pub const LABEL: Color32 = Color32::from_rgb(20, 60, 150);
pub const VALUE: Color32 = Color32::from_rgb(60, 60, 60);
pub const SELECT: Color32 = Color32::from_rgb(0, 140, 255);
pub const BOX_FILL: Color32 = Color32::from_rgb(236, 238, 244);

/// Live state shown on a symbol while simulating.
#[derive(Clone, Default)]
pub struct Live {
    pub glow: f32,
    pub reading: Option<String>,
}

pub struct Pen<'a> {
    pub painter: &'a Painter,
    pub origin: Pos2,
    pub s: f32,
    pub rot: u8,
    pub stroke: Stroke,
}

impl<'a> Pen<'a> {
    pub fn p(&self, x: f32, y: f32) -> Pos2 {
        let (rx, ry) = rotate_f(x, y, self.rot);
        self.origin + vec2(rx * self.s, ry * self.s)
    }
    pub fn line(&self, x1: f32, y1: f32, x2: f32, y2: f32) {
        self.painter.line_segment([self.p(x1, y1), self.p(x2, y2)], self.stroke);
    }
    pub fn line_w(&self, x1: f32, y1: f32, x2: f32, y2: f32, w: f32) {
        self.painter
            .line_segment([self.p(x1, y1), self.p(x2, y2)], Stroke::new(self.stroke.width * w, self.stroke.color));
    }
    pub fn poly(&self, pts: &[(f32, f32)], closed: bool) {
        let v: Vec<Pos2> = pts.iter().map(|&(x, y)| self.p(x, y)).collect();
        if closed {
            self.painter.add(Shape::closed_line(v, self.stroke));
        } else {
            self.painter.add(Shape::line(v, self.stroke));
        }
    }
    pub fn fill_poly(&self, pts: &[(f32, f32)], fill: Color32) {
        let v: Vec<Pos2> = pts.iter().map(|&(x, y)| self.p(x, y)).collect();
        self.painter.add(Shape::convex_polygon(v, fill, self.stroke));
    }
    pub fn circle(&self, x: f32, y: f32, r: f32) {
        self.painter.circle_stroke(self.p(x, y), r * self.s, self.stroke);
    }
    pub fn fill_circle(&self, x: f32, y: f32, r: f32, fill: Color32) {
        self.painter.circle_filled(self.p(x, y), r * self.s, fill);
    }
    pub fn rect(&self, x0: f32, y0: f32, x1: f32, y1: f32, fill: Color32) {
        self.fill_poly(&[(x0, y0), (x1, y0), (x1, y1), (x0, y1)], fill);
    }
    pub fn rect_screen(&self, x0: f32, y0: f32, x1: f32, y1: f32) -> Rect {
        Rect::from_two_pos(self.p(x0, y0), self.p(x1, y1))
    }
    pub fn text(&self, x: f32, y: f32, t: &str, size: f32, color: Color32, align: Align2) {
        let fs = (size * self.s).clamp(5.0, 40.0);
        self.painter.text(self.p(x, y), align, t, FontId::proportional(fs), color);
    }
    /// Text placed at a rotated anchor but never rotated itself.
    pub fn text_fixed(&self, pos: Pos2, t: &str, size: f32, color: Color32, align: Align2) {
        let fs = (size * self.s).clamp(5.0, 40.0);
        self.painter.text(pos, align, t, FontId::proportional(fs), color);
    }
}

fn arrow_head(pen: &Pen, tip: (f32, f32), from: (f32, f32), size: f32) {
    let (dx, dy) = (tip.0 - from.0, tip.1 - from.1);
    let len = (dx * dx + dy * dy).sqrt().max(1e-6);
    let (ux, uy) = (dx / len, dy / len);
    let (px, py) = (-uy, ux);
    let b = (tip.0 - ux * size, tip.1 - uy * size);
    pen.fill_poly(
        &[tip, (b.0 + px * size * 0.5, b.1 + py * size * 0.5), (b.0 - px * size * 0.5, b.1 - py * size * 0.5)],
        pen.stroke.color,
    );
}

fn sine_glyph(pen: &Pen, cx: f32, cy: f32, w: f32, h: f32) {
    let mut pts = Vec::new();
    for i in 0..=24 {
        let t = i as f32 / 24.0;
        pts.push((cx - w / 2.0 + w * t, cy - h / 2.0 * (t * std::f32::consts::TAU).sin()));
    }
    pen.poly(&pts, false);
}

fn plus(pen: &Pen, x: f32, y: f32, r: f32) {
    pen.line_w(x - r, y, x + r, y, 0.8);
    pen.line_w(x, y - r, x, y + r, 0.8);
}

pub fn draw_symbol(pen: &Pen, kind: Kind, params: &Params, live: &Live) {
    let ink = pen.stroke.color;
    match kind {
        Kind::Resistor => {
            pen.line(-3.0, 0.0, -2.0, 0.0);
            pen.poly(
                &[(-2.0, 0.0), (-1.67, -0.6), (-1.0, 0.6), (-0.33, -0.6), (0.33, 0.6), (1.0, -0.6), (1.67, 0.6), (2.0, 0.0)],
                false,
            );
            pen.line(2.0, 0.0, 3.0, 0.0);
        }
        Kind::Potentiometer => {
            pen.line(-3.0, 0.0, -2.0, 0.0);
            pen.poly(
                &[(-2.0, 0.0), (-1.67, -0.6), (-1.0, 0.6), (-0.33, -0.6), (0.33, 0.6), (1.0, -0.6), (1.67, 0.6), (2.0, 0.0)],
                false,
            );
            pen.line(2.0, 0.0, 3.0, 0.0);
            let wx = -2.0 + 4.0 * (params.setting as f32 / 100.0).clamp(0.0, 1.0);
            pen.poly(&[(0.0, -3.0), (0.0, -2.0), (wx, -2.0), (wx, -1.2)], false);
            arrow_head(pen, (wx, -0.7), (wx, -1.5), 0.6);
        }
        Kind::Capacitor => {
            pen.line(-3.0, 0.0, -0.35, 0.0);
            pen.line(0.35, 0.0, 3.0, 0.0);
            pen.line_w(-0.35, -1.1, -0.35, 1.1, 1.3);
            pen.line_w(0.35, -1.1, 0.35, 1.1, 1.3);
        }
        Kind::Inductor => {
            pen.line(-3.0, 0.0, -2.0, 0.0);
            let mut pts = Vec::new();
            for h in 0..4 {
                let cx = -1.5 + h as f32;
                for i in 0..=10 {
                    let a = std::f32::consts::PI * (1.0 + i as f32 / 10.0);
                    pts.push((cx + 0.5 * a.cos(), 0.6 * a.sin()));
                }
            }
            pen.poly(&pts, false);
            pen.line(2.0, 0.0, 3.0, 0.0);
        }
        Kind::DcVoltage => {
            pen.line(0.0, -3.0, 0.0, -0.4);
            pen.line_w(-1.3, -0.4, 1.3, -0.4, 1.0);
            pen.line_w(-0.6, 0.4, 0.6, 0.4, 2.2);
            pen.line(0.0, 0.4, 0.0, 3.0);
            plus(pen, 1.0, -1.3, 0.35);
        }
        Kind::DcCurrent => {
            pen.line(0.0, -3.0, 0.0, -1.4);
            pen.circle(0.0, 0.0, 1.4);
            pen.line(0.0, 0.9, 0.0, -0.3);
            arrow_head(pen, (0.0, -0.9), (0.0, 0.0), 0.6);
            pen.line(0.0, 1.4, 0.0, 3.0);
        }
        Kind::AcVoltage => {
            pen.line(0.0, -3.0, 0.0, -1.4);
            pen.circle(0.0, 0.0, 1.4);
            sine_glyph(pen, 0.0, 0.0, 1.8, 1.0);
            pen.line(0.0, 1.4, 0.0, 3.0);
            plus(pen, 1.3, -1.9, 0.3);
        }
        Kind::Ground => {
            pen.line(0.0, 0.0, 0.0, 0.8);
            pen.line_w(-1.4, 0.8, 1.4, 0.8, 1.2);
            pen.line_w(-0.9, 1.35, 0.9, 1.35, 1.2);
            pen.line_w(-0.4, 1.9, 0.4, 1.9, 1.2);
        }
        Kind::Diode | Kind::Zener | Kind::Led => {
            pen.line(-3.0, 0.0, -0.8, 0.0);
            pen.line(0.8, 0.0, 3.0, 0.0);
            let fill = if kind == Kind::Led && live.glow > 0.02 {
                let [r, g, b] = params.led.rgb();
                Color32::from_rgb(r, g, b)
            } else {
                ink
            };
            pen.fill_poly(&[(-0.8, -0.9), (-0.8, 0.9), (0.8, 0.0)], fill);
            if kind == Kind::Zener {
                pen.poly(&[(0.5, -1.1), (0.8, -0.9), (0.8, 0.9), (1.1, 1.1)], false);
            } else {
                pen.line(0.8, -0.9, 0.8, 0.9);
            }
            if kind == Kind::Led {
                pen.line(0.0, -1.1, 0.7, -1.8);
                arrow_head(pen, (0.9, -2.0), (0.0, -1.1), 0.45);
                pen.line(0.7, -0.9, 1.4, -1.6);
                arrow_head(pen, (1.6, -1.8), (0.7, -0.9), 0.45);
                if live.glow > 0.02 {
                    let [r, g, b] = params.led.rgb();
                    let a = (live.glow.clamp(0.0, 1.0) * 140.0) as u8;
                    pen.fill_circle(0.0, 0.0, 1.0 + 1.2 * live.glow.clamp(0.0, 1.0), Color32::from_rgba_unmultiplied(r, g, b, a));
                }
            }
        }
        Kind::Switch => {
            pen.line(-3.0, 0.0, -1.2, 0.0);
            pen.line(1.2, 0.0, 3.0, 0.0);
            pen.fill_circle(-1.2, 0.0, 0.2, ink);
            pen.fill_circle(1.2, 0.0, 0.2, ink);
            if params.closed {
                pen.line(-1.2, 0.0, 1.2, -0.15);
            } else {
                pen.line(-1.2, 0.0, 0.9, -1.2);
            }
        }
        Kind::Lamp => {
            if live.glow > 0.02 {
                let a = (live.glow.clamp(0.0, 1.0) * 220.0) as u8;
                pen.fill_circle(0.0, 0.0, 1.3 + 0.8 * live.glow.clamp(0.0, 1.0), Color32::from_rgba_unmultiplied(255, 220, 40, a));
            }
            pen.line(-3.0, 0.0, -1.3, 0.0);
            pen.line(1.3, 0.0, 3.0, 0.0);
            pen.circle(0.0, 0.0, 1.3);
            pen.line(-0.92, -0.92, 0.92, 0.92);
            pen.line(-0.92, 0.92, 0.92, -0.92);
        }
        Kind::Voltmeter | Kind::Ammeter => {
            pen.line(-4.0, 0.0, -3.0, 0.0);
            pen.line(3.0, 0.0, 4.0, 0.0);
            pen.rect(-3.0, -1.8, 3.0, 1.8, Color32::from_rgb(250, 250, 236));
            let r = pen.rect_screen(-3.0, -1.8, 3.0, 1.8);
            let txt = live.reading.clone().unwrap_or_else(|| if kind == Kind::Voltmeter { "---- V".into() } else { "---- A".into() });
            pen.text_fixed(r.center(), &txt, 0.95, Color32::BLACK, Align2::CENTER_CENTER);
            plus(pen, -2.4, -1.2, 0.3);
            pen.line_w(2.1, -1.2, 2.7, -1.2, 0.8);
        }
        Kind::Probe => {
            pen.line(0.0, 0.0, 1.0, -1.2);
            pen.fill_circle(0.0, 0.0, 0.25, ink);
            let r = Rect::from_two_pos(pen.origin + vec2(1.0 * pen.s, -3.2 * pen.s), pen.origin + vec2(5.6 * pen.s, -1.2 * pen.s));
            pen.painter.rect(r, 2.0, Color32::from_rgb(255, 250, 215), Stroke::new(1.0, Color32::from_rgb(200, 160, 0)));
            let txt = live.reading.clone().unwrap_or_else(|| "V: ---".into());
            pen.text_fixed(r.left_center() + vec2(3.0, 0.0), &txt, 0.85, Color32::BLACK, Align2::LEFT_CENTER);
        }
        Kind::Multimeter => {
            pen.line(-1.0, 3.0, -1.0, 4.0);
            pen.line(1.0, 3.0, 1.0, 4.0);
            pen.rect(-2.0, -3.0, 2.0, 3.0, BOX_FILL);
            pen.rect(-1.5, -2.4, 1.5, -0.8, Color32::from_rgb(196, 214, 170));
            pen.text(0.0, 0.6, "DMM", 0.8, ink, Align2::CENTER_CENTER);
            pen.text(-1.0, 2.3, "+", 0.9, ink, Align2::CENTER_CENTER);
            pen.text(1.0, 2.3, "−", 0.9, ink, Align2::CENTER_CENTER);
        }
        Kind::FuncGen => {
            for x in [-2.0, 0.0, 2.0] {
                pen.line(x, 3.0, x, 4.0);
            }
            pen.rect(-3.0, -3.0, 3.0, 3.0, BOX_FILL);
            sine_glyph(pen, 0.0, -0.8, 3.0, 2.0);
            pen.text(-2.0, 2.2, "+", 0.8, ink, Align2::CENTER_CENTER);
            pen.text(0.0, 2.2, "C", 0.75, ink, Align2::CENTER_CENTER);
            pen.text(2.0, 2.2, "−", 0.8, ink, Align2::CENTER_CENTER);
        }
        Kind::Oscilloscope => {
            for x in [-3.0, -1.0, 1.0, 3.0] {
                pen.line(x, 3.0, x, 4.0);
            }
            pen.rect(-4.0, -3.0, 4.0, 3.0, BOX_FILL);
            pen.rect(-3.3, -2.5, 3.3, 1.2, Color32::from_rgb(20, 30, 30));
            let green = Pen { painter: pen.painter, origin: pen.origin, s: pen.s, rot: pen.rot, stroke: Stroke::new(pen.stroke.width, Color32::from_rgb(80, 255, 120)) };
            sine_glyph(&green, 0.0, -0.65, 6.0, 2.2);
            for (x, t) in [(-3.0, "A"), (-1.0, "B"), (1.0, "T"), (3.0, "G")] {
                pen.text(x, 2.2, t, 0.75, ink, Align2::CENTER_CENTER);
            }
        }
    }
}

/// Draw the reference and value labels around a placed component.
pub fn draw_labels(painter: &Painter, comp: &Component, origin: Pos2, s: f32) {
    if comp.kind == Kind::Ground || comp.kind == Kind::Probe {
        if comp.kind == Kind::Probe {
            painter.text(
                origin + vec2(1.2 * s, -3.4 * s),
                Align2::LEFT_BOTTOM,
                &comp.refdes,
                FontId::proportional((0.85 * s).clamp(5.0, 30.0)),
                LABEL,
            );
        }
        return;
    }
    let (x0, y0, x1, y1) = comp.kind.bounds();
    let corners = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)];
    let mut r = Rect::NOTHING;
    for (x, y) in corners {
        let (rx, ry) = rotate_f(x, y, comp.rot);
        r.extend_with(origin + vec2(rx * s, ry * s));
    }
    let fs = (1.0 * s).clamp(5.0, 32.0);
    let val = comp.value_label();
    let vertical = comp.rot % 2 == 1 && !comp.kind.is_instrument();
    if comp.kind.is_instrument() {
        painter.text(pos2(r.center().x, r.top() - 2.0), Align2::CENTER_BOTTOM, &comp.refdes, FontId::proportional(fs), LABEL);
    } else if vertical || matches!(comp.kind, Kind::DcVoltage | Kind::DcCurrent | Kind::AcVoltage) && comp.rot % 2 == 0 {
        let x = r.right() + 0.4 * s;
        painter.text(pos2(x, r.center().y - 0.2 * s), Align2::LEFT_BOTTOM, &comp.refdes, FontId::proportional(fs), LABEL);
        painter.text(pos2(x, r.center().y + 0.2 * s), Align2::LEFT_TOP, &val, FontId::proportional(fs), VALUE);
    } else {
        painter.text(pos2(r.center().x, r.top() - 0.2 * s), Align2::CENTER_BOTTOM, &comp.refdes, FontId::proportional(fs), LABEL);
        if !val.is_empty() {
            painter.text(pos2(r.center().x, r.bottom() + 0.2 * s), Align2::CENTER_TOP, &val, FontId::proportional(fs), VALUE);
        }
    }
}

/// Small icon of a part for the parts bin.
pub fn draw_icon(painter: &Painter, rect: Rect, kind: Kind) {
    let (x0, y0, x1, y1) = kind.bounds();
    let w = (x1 - x0).max(1.0);
    let h = (y1 - y0).max(1.0);
    let s = (rect.width() / w).min(rect.height() / h) * 0.9;
    let cx = (x0 + x1) / 2.0;
    let cy = (y0 + y1) / 2.0;
    let origin = rect.center() - vec2(cx * s, cy * s);
    let pen = Pen { painter, origin, s, rot: 0, stroke: Stroke::new(1.2, INK) };
    let mut p = kind.default_params();
    if kind == Kind::Switch {
        p.closed = false;
    }
    draw_symbol(&pen, kind, &p, &Live::default());
}

