    } else if vertical || matches!(comp.kind, Kind::DcVoltage | Kind::DcCurrent | Kind::AcVoltage) && comp.rot % 2 == 0 {
        let x = r.right() + 0.4 * s;
        painter.text(pos2(x, r.center().y - 0.2 * s), Align2::LEFT_BOTTOM, &comp.refdes, FontId::proportional(fs), LABEL);
        painter.text(pos2(x, r.center().y + 0.2 * s), Align2::LEFT_TOP, &val, FontId::proportional(fs), VALUE);
    } else {
        painter.text(pos2(r.center().x, r.top() - 0.2 * s), Align2::CENTER_BOTTOM, &comp.refdes, FontId::proportional(fs), LABEL);
        if !val.is_empty() {
