const GRID: f32 = 10.0;
const FILE_EXT: &str = "cbs";

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
enum Sel {
    Comp(u64),
    Wire(u64),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Tool {
    Select,
    Wire,
    Place(Kind),
}

enum Drag {
    None,
    Move { start: GP, delta: GP, orig: Circuit },
    Band { start: Pos2 },
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum BottomTab {
    Results,
    Nets,
    Components,
    Erc,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AnalysisKind {
    Interactive,
    DcOp,
    Ac,
    Transient,
    DcSweep,
}

struct AnalysisCfg {
    sel: AnalysisKind,
    ac_fstart: f64,
    ac_fstop: f64,
    ac_ppd: usize,
    tr_stop: f64,
    tr_step: f64,
    tr_use_op: bool,
    dc_src: Option<u64>,
    dc_start: f64,
    dc_stop: f64,
    dc_incr: f64,
    out_vars: HashSet<String>,
    max_step: f64,
    ic_op: bool,
}

impl Default for AnalysisCfg {
    fn default() -> Self {
        AnalysisCfg {
            sel: AnalysisKind::Transient,
            ac_fstart: 1.0,
            ac_fstop: 10e6,
            ac_ppd: 20,
            tr_stop: 5e-3,
            tr_step: 5e-6,
            tr_use_op: false,
            dc_src: None,
            dc_start: 0.0,
            dc_stop: 10.0,
            dc_incr: 0.1,
            out_vars: HashSet::new(),
            max_step: 0.0,
            ic_op: false,
        }
    }
}

enum GraphTab {
    Op { title: String, rows: Vec<(String, f64, &'static str)> },
    Xy { title: String, xlabel: String, xunit: &'static str, series: Vec<sim::Series> },
    Ac { title: String, series: Vec<sim::AcSeries> },
}

impl GraphTab {
    fn title(&self) -> &str {
        match self {
            GraphTab::Op { title, .. } | GraphTab::Xy { title, .. } | GraphTab::Ac { title, .. } => title,
        }
    }
}

struct FileDlg {
    save: bool,
    netlist: bool,
    dir: PathBuf,
    name: String,
    err: Option<String>,
}

pub struct App {
    circuit: Circuit,
    undo: Vec<Circuit>,
    redo: Vec<Circuit>,
    file_path: Option<PathBuf>,
    dirty: bool,

    zoom: f32,
    pan: egui::Vec2,
    need_fit: bool,
    show_grid: bool,
    show_nets: bool,
    show_parts: bool,
    show_sheet: bool,

    tool: Tool,
    place_rot: u8,
    wiring: Option<Vec<GP>>,
    drag: Drag,
    selection: HashSet<Sel>,
    clipboard: (Vec<Component>, Vec<Wire>),
    paste_count: i32,
    hover_info: String,

    props: Option<u64>,
    props_orig: Option<Circuit>,
    wire_props: Option<u64>,
    open_inst: Vec<u64>,
    analysis_open: bool,
    cfg: AnalysisCfg,
    graphs: Vec<GraphTab>,
    graph_sel: usize,
    grapher_open: bool,
    file_dlg: Option<FileDlg>,
    about_open: bool,
    help_open: bool,
    confirm_new: Option<Option<usize>>,

    sim: Option<Sim>,
    running: bool,
    paused: bool,
    sim_error: Option<String>,
    meters: HashMap<u64, Meter>,
    scopes: HashMap<u64, Scope>,
    live: HashMap<u64, Live>,
    steps_last_frame: usize,
    h_used: f64,

    messages: Vec<String>,
    bottom_tab: BottomTab,
    last_frame: Option<Instant>,

    frame: u64,
    screenshot: Option<PathBuf>,
    shot_requested: bool,
}

fn default_dir() -> PathBuf {
    let home = std::env::var("HOME").or_else(|_| std::env::var("USERPROFILE")).map(PathBuf::from).unwrap_or_else(|_| PathBuf::from("."));
    let docs = home.join("Documents");
    if docs.is_dir() {
        docs
    } else {
        home
    }
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>, example: Option<usize>, open_file: Option<PathBuf>) -> Self {
        let mut visuals = egui::Visuals::light();
        visuals.panel_fill = Color32::from_rgb(232, 235, 241);
        visuals.window_fill = Color32::from_rgb(244, 246, 250);
        visuals.selection.bg_fill = Color32::from_rgb(160, 200, 250);
        visuals.selection.stroke = Stroke::new(1.0, Color32::from_rgb(20, 60, 150));
        cc.egui_ctx.set_visuals(visuals);
        let mut style = (*cc.egui_ctx.style()).clone();
        style.spacing.item_spacing = vec2(6.0, 4.0);
        cc.egui_ctx.set_style(style);

        let ex = example.unwrap_or(0);
        let circuit = examples::by_index(ex);
        let mut app = App {
            circuit,
            undo: Vec::new(),
            redo: Vec::new(),
            file_path: None,
            dirty: false,
            zoom: 1.6,
            pan: vec2(400.0, 300.0),
            need_fit: true,
            show_grid: true,
            show_nets: false,
            show_parts: true,
            show_sheet: true,
            tool: Tool::Select,
            place_rot: 0,
            wiring: None,
            drag: Drag::None,
            selection: HashSet::new(),
            clipboard: (Vec::new(), Vec::new()),
            paste_count: 0,
            hover_info: String::new(),
            props: None,
            props_orig: None,
            wire_props: None,
            open_inst: Vec::new(),
            analysis_open: false,
            cfg: AnalysisCfg::default(),
            graphs: Vec::new(),
            graph_sel: 0,
            grapher_open: false,
            file_dlg: None,
            about_open: false,
            help_open: false,
            confirm_new: None,
            sim: None,
            running: false,
            paused: false,
            sim_error: None,
            meters: HashMap::new(),
            scopes: HashMap::new(),
            live: HashMap::new(),
            steps_last_frame: 0,
            h_used: 0.0,
            messages: vec!["Welcome to Circuit Bench. The RC low-pass filter example is running — press Stop to edit it, or open another example from File ▸ Examples.".into()],
            bottom_tab: BottomTab::Results,
            last_frame: None,
            frame: 0,
            screenshot,
            shot_requested: false,
        };
        if let Some(p) = open_file {
            app.load_file(&p);
        }
        app.setup_example_instruments();
        // Open the first instrument panel and start the demo so the bench is alive on launch.
        if let Some(id) = app.circuit.components.iter().find(|c| c.kind == Kind::Oscilloscope).map(|c| c.id) {
            app.open_inst.push(id);
        } else if let Some(id) = app.circuit.components.iter().find(|c| c.kind == Kind::Multimeter).map(|c| c.id) {
            app.open_inst.push(id);
        }
        app.start_sim();
        app
    }

    fn setup_example_instruments(&mut self) {
        // sensible oscilloscope defaults for the loaded circuit
        let fmax = self
            .circuit
            .components
            .iter()
            .filter(|c| matches!(c.kind, Kind::FuncGen | Kind::AcVoltage))
            .map(|c| c.params.freq)
            .fold(0.0, f64::max);
        let amp = self
            .circuit
            .components
            .iter()
            .filter(|c| matches!(c.kind, Kind::FuncGen | Kind::AcVoltage))
            .map(|c| c.params.value.abs() + c.params.offset.abs())
            .fold(0.0, f64::max);
        for c in &self.circuit.components {
            if c.kind == Kind::Oscilloscope {
                let sc = self.scopes.entry(c.id).or_default();
                if fmax > 0.0 {
                    // about two periods on screen
                    let mut tb = 1e-9;
                    while tb * 10.0 < 2.0 / fmax {
                        tb = instruments::step_125(tb, true);
                    }
                    sc.timebase = tb;
                }
                if amp > 0.0 {
                    let mut v = 0.01;
                    while v * 4.0 < amp * 1.6 {
                        v = instruments::step_125(v, true);
                    }
                    sc.ch[0].scale = v;
                    sc.ch[1].scale = v;
                }
            }
        }
    }

    // ------------------------------------------------------------ edit helpers

    fn push_undo(&mut self, orig: Circuit) {
        self.undo.push(orig);
        if self.undo.len() > 200 {
            self.undo.remove(0);
        }
        self.redo.clear();
        self.dirty = true;
    }

    fn checkpoint(&mut self) {
        let c = self.circuit.clone();
        self.push_undo(c);
    }

    /// Structural edits stop the simulation, like a real bench: power off before rewiring.
    fn edit_stop(&mut self) {
        if self.running {
            self.stop_sim();
            self.log("Simulation stopped because the circuit was edited.");
        }
    }

    fn do_undo(&mut self) {
        if let Some(prev) = self.undo.pop() {
            self.edit_stop();
            let cur = std::mem::replace(&mut self.circuit, prev);
            self.redo.push(cur);
            self.selection.clear();
            self.dirty = true;
        }
    }

    fn do_redo(&mut self) {
        if let Some(next) = self.redo.pop() {
            self.edit_stop();
            let cur = std::mem::replace(&mut self.circuit, next);
            self.undo.push(cur);
            self.selection.clear();
            self.dirty = true;
        }
    }

    fn log(&mut self, s: impl Into<String>) {
        self.messages.push(s.into());
        if self.messages.len() > 500 {
            self.messages.remove(0);
        }
    }

    fn selected_comps(&self) -> HashSet<u64> {
        self.selection.iter().filter_map(|s| if let Sel::Comp(id) = s { Some(*id) } else { None }).collect()
    }
    fn selected_wires(&self) -> HashSet<u64> {
        self.selection.iter().filter_map(|s| if let Sel::Wire(id) = s { Some(*id) } else { None }).collect()
    }

    fn delete_selection(&mut self) {
        if self.selection.is_empty() {
            return;
        }
        self.edit_stop();
        self.checkpoint();
        let comps = self.selected_comps();
        let wires = self.selected_wires();
        let mut dead_pins: HashSet<GP> = HashSet::new();
        for c in &self.circuit.components {
            if comps.contains(&c.id) {
                dead_pins.extend(c.pin_positions());
            }
        }
        // pins of remaining parts stay connected
        let mut live_pins: HashSet<GP> = HashSet::new();
        for c in &self.circuit.components {
            if !comps.contains(&c.id) {
                live_pins.extend(c.pin_positions());
            }
        }
        self.circuit.components.retain(|c| !comps.contains(&c.id));
        self.circuit.wires.retain(|w| {
            if wires.contains(&w.id) {
                return false;
            }
            let f = w.points[0];
            let l = *w.points.last().unwrap();
            let touches_dead = (dead_pins.contains(&f) && !live_pins.contains(&f)) || (dead_pins.contains(&l) && !live_pins.contains(&l));
            !touches_dead
        });
        self.open_inst.retain(|id| !comps.contains(id));
        self.selection.clear();
    }

    fn copy_selection(&mut self) {
        let comps = self.selected_comps();
        let wires = self.selected_wires();
        let cs: Vec<Component> = self.circuit.components.iter().filter(|c| comps.contains(&c.id)).cloned().collect();
        let ws: Vec<Wire> = self.circuit.wires.iter().filter(|w| wires.contains(&w.id)).cloned().collect();
        if !cs.is_empty() || !ws.is_empty() {
            self.clipboard = (cs, ws);
            self.paste_count = 0;
        }
    }

    fn paste(&mut self) {
        if self.clipboard.0.is_empty() && self.clipboard.1.is_empty() {
            return;
        }
        self.edit_stop();
        self.checkpoint();
        self.paste_count += 1;
        let off = GP::new(4 * self.paste_count, 4 * self.paste_count);
        self.selection.clear();
        let (cs, ws) = self.clipboard.clone();
        for mut c in cs {
            c.id = self.circuit.new_id();
            c.refdes = self.circuit.next_refdes(c.kind);
            c.pos = c.pos.add(off);
            self.selection.insert(Sel::Comp(c.id));
            self.circuit.components.push(c);
        }
        for mut w in ws {
            w.id = self.circuit.new_id();
            for p in w.points.iter_mut() {
                *p = p.add(off);
            }
            self.selection.insert(Sel::Wire(w.id));
            self.circuit.wires.push(w);
        }
    }

    fn rotate_selection(&mut self, ccw: bool) {
        let comps = self.selected_comps();
        if comps.is_empty() {
            return;
        }
        self.edit_stop();
        let orig = self.circuit.clone();
        for c in self.circuit.components.iter_mut() {
            if comps.contains(&c.id) {
                c.rot = (c.rot + if ccw { 3 } else { 1 }) % 4;
            }
        }
        reroute(&orig, &mut self.circuit, &comps, None, &HashSet::new());
        self.push_undo(orig);
    }

    fn new_circuit(&mut self, example: Option<usize>) {
        self.stop_sim();
        self.circuit = match example {
            Some(i) => examples::by_index(i),
            None => Circuit { title: "Untitled".into(), ..Default::default() },
        };
        self.undo.clear();
        self.redo.clear();
        self.selection.clear();
        self.file_path = None;
        self.dirty = false;
        self.open_inst.clear();
        self.scopes.clear();
        self.meters.clear();
        self.live.clear();
        self.need_fit = true;
        self.cfg.out_vars.clear();
        if let Some(i) = example {
            self.setup_example_instruments();
            self.log(format!("Opened example: {}", examples::NAMES[i.min(examples::NAMES.len() - 1)]));
            if let Some(id) = self.circuit.components.iter().find(|c| c.kind.is_instrument() && c.kind != Kind::FuncGen).map(|c| c.id) {
                self.open_inst.push(id);
            }
        }
    }

    fn load_file(&mut self, p: &Path) {
        match std::fs::read_to_string(p).map_err(|e| e.to_string()).and_then(|s| serde_json::from_str::<Circuit>(&s).map_err(|e| e.to_string())) {
            Ok(c) => {
                self.new_circuit(None);
                self.circuit = c;
                self.file_path = Some(p.to_path_buf());
                self.setup_example_instruments();
                self.log(format!("Opened {}", p.display()));
            }
            Err(e) => self.log(format!("Could not open {}: {}", p.display(), e)),
        }
    }

    fn save_file(&mut self, p: &Path) -> Result<(), String> {
        let txt = serde_json::to_string_pretty(&self.circuit).map_err(|e| e.to_string())?;
        std::fs::write(p, txt).map_err(|e| e.to_string())?;
        self.file_path = Some(p.to_path_buf());
        self.dirty = false;
        self.log(format!("Saved {}", p.display()));
        Ok(())
    }

    fn save(&mut self) {
        if let Some(p) = self.file_path.clone() {
            if let Err(e) = self.save_file(&p) {
                self.log(format!("Save failed: {}", e));
            }
        } else {
            self.open_file_dlg(true, false);
        }
    }

    fn open_file_dlg(&mut self, save: bool, netlist: bool) {
        let dir = self.file_path.as_ref().and_then(|p| p.parent().map(|d| d.to_path_buf())).unwrap_or_else(default_dir);
        let base = self.circuit.title.replace(['/', '\\', ':'], "_");
        let base = if base.trim().is_empty() { "circuit".to_string() } else { base };
        let name = if netlist {
            format!("{}.cir", base)
        } else if save {
            self.file_path.as_ref().and_then(|p| p.file_name()).map(|n| n.to_string_lossy().to_string()).unwrap_or(format!("{}.{}", base, FILE_EXT))
        } else {
            String::new()
        };
        self.file_dlg = Some(FileDlg { save, netlist, dir, name, err: None });
    }

    // ------------------------------------------------------------ simulation

    fn start_sim(&mut self) {
        self.sim_error = None;
        match Sim::new(&self.circuit) {
            Ok(mut s) => {
                if self.cfg.ic_op {
                    if let Err(e) = s.dc_op() {
                        self.log(format!("Initial operating point failed, starting from zero: {}", e));
                    }
                }
                self.sim = Some(s);
                self.running = true;
                self.paused = false;
                for sc in self.scopes.values_mut() {
                    sc.reset();
                }
                self.meters.clear();
                self.live.clear();
                self.last_frame = None;
            }
            Err(e) => {
                self.sim_error = Some(e.clone());
                self.log(format!("Simulation error: {}", e));
                self.running = false;
                self.bottom_tab = BottomTab::Results;
            }
        }
    }

    fn stop_sim(&mut self) {
        self.sim = None;
        self.running = false;
        self.paused = false;
        for l in self.live.values_mut() {
            l.glow = 0.0;
        }
    }

    fn time_step(&self, sim: &Sim) -> f64 {
        if self.cfg.max_step > 0.0 {
            return self.cfg.max_step;
        }
        let f = sim.max_freq();
        if f > 0.0 {
            1.0 / (f * 200.0)
        } else {
            1e-5
        }
    }

    fn run_sim_frame(&mut self) {
        let now = Instant::now();
        let dt_real = self.last_frame.map(|t| now.duration_since(t).as_secs_f64()).unwrap_or(1.0 / 60.0).clamp(0.001, 0.05);
        self.last_frame = Some(now);
        let Some(mut sim) = self.sim.take() else {
            return;
        };
        if !sim.refresh(&self.circuit) {
            // structure changed (e.g. meter mode): restart
            self.sim = None;
            self.start_sim();
            return;
        }
        let h = self.time_step(&sim);
        self.h_used = h;
        let fmax = sim.max_freq();
        let window = if fmax > 0.0 { 3.0 / fmax } else { 0.0 };
        let target_steps = ((dt_real / h).ceil() as usize).max(1);
        let budget = std::time::Duration::from_millis(12);
        let mut steps = 0;
        let mut err = None;
        while steps < target_steps {
            if let Err(e) = sim.step(h) {
                err = Some(e);
                break;
            }
            steps += 1;
            sample(&self.circuit, &sim, &mut self.meters, &mut self.scopes, window);
            if steps % 32 == 0 && now.elapsed() > budget {
                break;
            }
        }
        self.steps_last_frame = steps;
        if let Some(e) = err {
            self.log(format!("Simulation error at t = {}: {}", fmt_si(sim.t, "s"), e));
            self.sim_error = Some(e);
            self.running = false;
            self.sim = None;
            return;
        }
        for sc in self.scopes.values_mut() {
            sc.update_display();
        }
        self.update_live(&sim, fmax);
        self.sim = Some(sim);
    }

    fn update_live(&mut self, sim: &Sim, fmax: f64) {
        for c in &self.circuit.components {
            let m = self.meters.get(&c.id);
            let live = self.live.entry(c.id).or_default();
            let Some(m) = m else {
                continue;
            };
            match c.kind {
                Kind::Voltmeter | Kind::Ammeter => {
                    let unit = if c.kind == Kind::Voltmeter { "V" } else { "A" };
                    let v = if c.params.ac { m.ac_rms() } else { m.mean() };
                    live.reading = Some(fmt_reading(v, unit));
                }
                Kind::Multimeter => {
                    live.reading = Some(multimeter_text(c, m));
                }
                Kind::Probe => {
                    live.reading = Some(if fmax > 0.0 {
                        format!("Vpp {}  Vrms {}", fmt_si(m.peak_to_peak(), "V"), fmt_si((m.ac_rms().powi(2) + m.mean().powi(2)).sqrt(), "V"))
                    } else {
                        format!("V: {}", fmt_reading(m.mean(), "V"))
                    });
                }
                Kind::Led => {
                    let i = m.mean();
                    live.glow = if i > 0.5e-3 { (i / 0.01).clamp(0.15, 1.0) as f32 } else { 0.0 };
                    live.reading = Some(fmt_reading(i, "A"));
                }
                Kind::Lamp => {
                    let p = m.mean();
                    live.glow = if c.params.power > 0.0 { (p / c.params.power).clamp(0.0, 1.0) as f32 } else { 0.0 };
                    live.reading = Some(fmt_reading(p, "W"));
                }
                _ => {}
            }
        }
        let _ = sim;
    }

    // ------------------------------------------------------------ keyboard

    fn handle_keys(&mut self, ctx: &egui::Context) {
        if ctx.wants_keyboard_input() {
            return;
        }
        let events = ctx.input(|i| i.events.clone());
        for ev in events {
            if let egui::Event::Key { key, pressed: true, modifiers, repeat: false, .. } = ev {
                let cmd = modifiers.command;
                // interactive keys for switches and potentiometers while simulating
                if self.running && !cmd {
                    let ch = match key {
                        Key::Space => Some(' '),
                        k => {
                            let n = k.name();
                            if n.chars().count() == 1 {
                                n.chars().next()
                            } else {
                                None
                            }
                        }
                    };
                    if let Some(ch) = ch {
                        let mut used = false;
                        for c in self.circuit.components.iter_mut() {
                            if c.params.key.to_ascii_uppercase() != ch.to_ascii_uppercase() {
                                continue;
                            }
                            match c.kind {
                                Kind::Switch => {
                                    c.params.closed = !c.params.closed;
                                    used = true;
                                }
                                Kind::Potentiometer => {
                                    let d = if modifiers.shift { -c.params.increment } else { c.params.increment };
                                    c.params.setting = (c.params.setting + d).clamp(0.0, 100.0);
                                    used = true;
                                }
                                _ => {}
                            }
                        }
                        if used {
                            continue;
                        }
                    }
                }
                match key {
                    Key::Z if cmd && modifiers.shift => self.do_redo(),
                    Key::Z if cmd => self.do_undo(),
                    Key::Y if cmd => self.do_redo(),
                    Key::C if cmd => self.copy_selection(),
                    Key::X if cmd => {
                        self.copy_selection();
                        self.delete_selection();
                    }
                    Key::V if cmd => self.paste(),
                    Key::A if cmd => {
                        self.selection = self.circuit.components.iter().map(|c| Sel::Comp(c.id)).chain(self.circuit.wires.iter().map(|w| Sel::Wire(w.id))).collect();
                    }
                    Key::S if cmd => self.save(),
                    Key::O if cmd => self.open_file_dlg(false, false),
                    Key::N if cmd => self.confirm_new = Some(None),
                    Key::R if cmd => self.rotate_selection(modifiers.shift),
                    Key::R => {
                        if let Tool::Place(_) = self.tool {
                            self.place_rot = (self.place_rot + 1) % 4;
                        } else {
                            self.rotate_selection(modifiers.shift);
                        }
                    }
                    Key::Delete | Key::Backspace => self.delete_selection(),
                    Key::Escape => {
                        if self.wiring.is_some() {
                            self.wiring = None;
                        } else {
                            self.tool = Tool::Select;
                            self.selection.clear();
                        }
                    }
                    Key::W if !cmd => {
                        self.tool = if self.tool == Tool::Wire { Tool::Select } else { Tool::Wire };
                    }
                    Key::F5 => self.toggle_run(),
                    Key::F6 => {
                        if self.running {
                            self.paused = !self.paused;
                        }
                    }
                    Key::F7 => self.need_fit = true,
                    Key::Plus | Key::Equals if cmd => self.zoom = (self.zoom * 1.25).min(8.0),
                    Key::Minus if cmd => self.zoom = (self.zoom / 1.25).max(0.25),
                    _ => {}
                }
            }
        }
    }

    fn toggle_run(&mut self) {
        if self.running {
            self.stop_sim();
            self.log("Simulation stopped.");
        } else {
            self.start_sim();
            if self.running {
                self.log("Interactive simulation running.");
            }
        }
    }

    // ------------------------------------------------------------ canvas

    fn fit_view(&mut self, rect: Rect) {
        let mut lo = (f32::MAX, f32::MAX);
        let mut hi = (f32::MIN, f32::MIN);
        let mut any = false;
        for c in &self.circuit.components {
            let (x0, y0, x1, y1) = c.kind.bounds();
            for (x, y) in [(x0, y0 - 2.5), (x1, y1 + 2.5)] {
                let (rx, ry) = rotate_f(x, y, c.rot);
                let (wx, wy) = (c.pos.x as f32 + rx, c.pos.y as f32 + ry);
                lo = (lo.0.min(wx), lo.1.min(wy));
                hi = (hi.0.max(wx), hi.1.max(wy));
                any = true;
            }
        }
        for w in &self.circuit.wires {
            for p in &w.points {
                lo = (lo.0.min(p.x as f32), lo.1.min(p.y as f32));
                hi = (hi.0.max(p.x as f32), hi.1.max(p.y as f32));
                any = true;
            }
        }
        if !any {
            self.zoom = 1.6;
            self.pan = rect.size() / 2.0;
            return;
        }
        let w = (hi.0 - lo.0 + 8.0) * GRID;
        let h = (hi.1 - lo.1 + 8.0) * GRID;
        self.zoom = (rect.width() / w).min(rect.height() / h).clamp(0.4, 3.0);
        let s = GRID * self.zoom;
        let cx = (lo.0 + hi.0) / 2.0;
        let cy = (lo.1 + hi.1) / 2.0;
        self.pan = rect.size() / 2.0 - vec2(cx * s, cy * s);
    }

    fn comp_screen_rect(c: &Component, origin: Pos2, s: f32) -> Rect {
        let (x0, y0, x1, y1) = c.kind.bounds();
        let mut r = Rect::NOTHING;
        for (x, y) in [(x0, y0), (x1, y0), (x1, y1), (x0, y1)] {
            let (rx, ry) = rotate_f(x, y, c.rot);
            r.extend_with(origin + vec2((c.pos.x as f32 + rx) * s, (c.pos.y as f32 + ry) * s));
        }
        r
    }

    fn canvas(&mut self, ui: &mut Ui) {
        let (resp, painter) = ui.allocate_painter(ui.available_size(), Sense::click_and_drag());
        let rect = resp.rect;
        if self.need_fit {
            self.fit_view(rect);
            self.need_fit = false;
        }
        // zoom / pan with wheel and trackpad
        if resp.hovered() {
            let (scroll, zd, hover) = ui.input(|i| (i.smooth_scroll_delta, i.zoom_delta(), i.pointer.hover_pos()));
            if zd != 1.0 {
                if let Some(m) = hover {
                    let old_s = GRID * self.zoom;
                    let world = (m - rect.min - self.pan) / old_s;
                    self.zoom = (self.zoom * zd).clamp(0.25, 8.0);
                    let new_s = GRID * self.zoom;
                    self.pan = m - rect.min - world * new_s;
                }
            } else if scroll != egui::Vec2::ZERO {
                self.pan += scroll;
            }
        }
        if resp.dragged_by(egui::PointerButton::Middle) || resp.dragged_by(egui::PointerButton::Secondary) {
            self.pan += resp.drag_delta();
        }
        let s = GRID * self.zoom;
        let origin = rect.min + self.pan;
        let to_screen = |p: GP| origin + vec2(p.x as f32 * s, p.y as f32 * s);
        let to_world = |q: Pos2| ((q.x - origin.x) / s, (q.y - origin.y) / s);

        // sheet & grid
        painter.rect_filled(rect, 0.0, Color32::WHITE);
        if self.show_grid && s >= 4.0 {
            let step = if s < 7.0 { 2 } else { 1 };
            let (wx0, wy0) = to_world(rect.min);
            let (wx1, wy1) = to_world(rect.max);
            let dot = Color32::from_rgb(190, 196, 210);
            let mut gx = (wx0.floor() as i32 / step) * step;
            while gx as f32 <= wx1 {
                let mut gy = (wy0.floor() as i32 / step) * step;
                while gy as f32 <= wy1 {
                    let p = to_screen(GP::new(gx, gy));
                    let major = gx % 10 == 0 && gy % 10 == 0;
                    painter.circle_filled(p, if major { 1.3 } else { 0.8 }, dot);
                    gy += step;
                }
                gx += step;
            }
        }

        // ---- hit testing
        let hover = resp.hover_pos();
        let mw = hover.map(to_world);
        let snapped = mw.map(|(x, y)| GP::new(x.round() as i32, y.round() as i32));
        let mut hover_pin: Option<GP> = None;
        let mut hover_comp: Option<u64> = None;
        let mut hover_wire: Option<u64> = None;
        if let Some((x, y)) = mw {
            let mut best = 0.65f32;
            for c in &self.circuit.components {
                for p in c.pin_positions() {
                    let d = ((p.x as f32 - x).powi(2) + (p.y as f32 - y).powi(2)).sqrt();
                    if d < best {
                        best = d;
                        hover_pin = Some(p);
                    }
                }
            }
            for c in self.circuit.components.iter().rev() {
                let (x0, y0, x1, y1) = c.kind.bounds();
                let inv = (4 - c.rot % 4) % 4;
                let (lx, ly) = rotate_f(x - c.pos.x as f32, y - c.pos.y as f32, inv);
                let m = 0.3;
                if lx >= x0 - m && lx <= x1 + m && ly >= y0 - m && ly <= y1 + m {
                    hover_comp = Some(c.id);
                    break;
                }
            }
            if hover_comp.is_none() {
                for w in self.circuit.wires.iter().rev() {
                    for k in 1..w.points.len() {
                        if seg_dist((x, y), w.points[k - 1], w.points[k]) < 0.5 {
                            hover_wire = Some(w.id);
                            break;
                        }
                    }
                    if hover_wire.is_some() {
                        break;
                    }
                }
            }
        }
        // body of an instrument has priority over its pins only when far from them
        if self.tool == Tool::Select && self.wiring.is_none() && hover_pin.is_some() && matches!(self.drag, Drag::None) {
            ui.ctx().set_cursor_icon(egui::CursorIcon::Crosshair);
        }

        // ---- input
        let (pressed, released, down, shift, ptr) = ui.input(|i| (i.pointer.primary_pressed(), i.pointer.primary_released(), i.pointer.primary_down(), i.modifiers.shift, i.pointer.interact_pos()));
        let dbl = resp.double_clicked();
        if pressed && resp.hovered() {
            if let Some(sp) = snapped {
                self.on_press(sp, hover_pin, hover_comp, hover_wire, shift, ptr.unwrap_or(rect.center()));
            }
        }
        if down {
            if let (Drag::Move { start, delta, orig }, Some(sp)) = (&mut self.drag, snapped) {
                let d = sp.sub(*start);
                if d != *delta {
                    *delta = d;
                    let orig = orig.clone();
                    let comps = self.selected_comps();
                    let wires = self.selected_wires();
                    let mut c = orig.clone();
                    for comp in c.components.iter_mut() {
                        if comps.contains(&comp.id) {
                            comp.pos = comp.pos.add(d);
                        }
                    }
                    reroute(&orig, &mut c, &comps, Some(d), &wires);
                    self.circuit = c;
                }
            }
        }
        if released {
            match std::mem::replace(&mut self.drag, Drag::None) {
                Drag::Move { delta, orig, .. } => {
                    if delta != GP::new(0, 0) {
                        self.push_undo(orig);
                        self.edit_stop();
                    }
                }
                Drag::Band { start } => {
                    if let Some(end) = ptr {
                        let r = Rect::from_two_pos(start, end);
                        if r.width() > 3.0 || r.height() > 3.0 {
                            for c in &self.circuit.components {
                                if r.contains(Self::comp_screen_rect(c, origin, s).center()) {
                                    self.selection.insert(Sel::Comp(c.id));
                                }
                            }
                            for w in &self.circuit.wires {
                                if w.points.iter().all(|p| r.contains(to_screen(*p))) {
                                    self.selection.insert(Sel::Wire(w.id));
                                }
                            }
                        }
                    }
                }
                Drag::None => {}
            }
        }
        if dbl {
            if self.wiring.is_some() {
                self.finish_wire();
            } else if let Some(id) = hover_comp {
                self.open_props(id);
            } else if let Some(id) = hover_wire {
                self.wire_props = Some(id);
            }
        }
        if resp.secondary_clicked() && self.wiring.is_some() {
            self.wiring = None;
        }

        // hover info
        self.hover_info.clear();
        if let Some(sim) = &self.sim {
            let net = if let Some(p) = hover_pin {
                self.circuit.components.iter().enumerate().find_map(|(ci, c)| c.pin_positions().iter().position(|q| *q == p).map(|k| sim.nl.comp_nets.get(ci).map(|v| v[k])).flatten())
            } else if let Some(wid) = hover_wire {
                self.circuit.wires.iter().position(|w| w.id == wid).and_then(|i| sim.nl.wire_nets.get(i).copied()).filter(|n| *n != usize::MAX)
            } else {
                None
            };
            if let Some(n) = net {
                self.hover_info = format!("Net {}: {}", n, fmt_reading(sim.v(n), "V"));
            }
        }

        // ---- draw wires
        let sel_w = self.selected_wires();
        let wire_w = (0.16 * s).clamp(1.0, 4.0);
        let net_of_wire: Option<&Vec<usize>> = self.sim.as_ref().map(|s| &s.nl.wire_nets);
        for (wi, w) in self.circuit.wires.iter().enumerate() {
            let [r, g, b] = w.color.rgb();
            let col = if sel_w.contains(&w.id) { SELECT } else { Color32::from_rgb(r, g, b) };
            let pts: Vec<Pos2> = w.points.iter().map(|p| to_screen(*p)).collect();
            if sel_w.contains(&w.id) {
                painter.add(Shape::line(pts.clone(), Stroke::new(wire_w + 3.0, Color32::from_rgba_unmultiplied(0, 140, 255, 60))));
            }
            if hover_wire == Some(w.id) && self.tool == Tool::Select {
                painter.add(Shape::line(pts.clone(), Stroke::new(wire_w + 2.0, Color32::from_rgba_unmultiplied(0, 0, 0, 30))));
            }
            painter.add(Shape::line(pts, Stroke::new(wire_w, col)));
            if self.show_nets && w.points.len() >= 2 {
                let label = net_of_wire.and_then(|v| v.get(wi).copied()).filter(|n| *n != usize::MAX).map(|n| n.to_string());
                if let Some(label) = label {
                    let a = to_screen(w.points[0]);
                    let b = to_screen(w.points[1]);
                    let m = pos2((a.x + b.x) / 2.0, (a.y + b.y) / 2.0);
                    painter.text(m + vec2(2.0, -2.0), Align2::LEFT_BOTTOM, label, FontId::proportional((0.9 * s).clamp(8.0, 18.0)), Color32::from_rgb(0, 120, 0));
                }
            }
        }
        // junction dots
        for p in junctions(&self.circuit) {
            painter.circle_filled(to_screen(p), (0.3 * s).clamp(2.0, 6.0), Color32::from_rgb(200, 30, 30));
        }

        // ---- draw components
        let sel_c = self.selected_comps();
        let stroke_w = (0.13 * s).clamp(1.0, 3.0);
        let empty = Live::default();
        for c in &self.circuit.components {
            let selected = sel_c.contains(&c.id);
            let o = to_screen(c.pos);
            let pen = Pen { painter: &painter, origin: o, s, rot: c.rot, stroke: Stroke::new(stroke_w, if selected { SELECT } else { INK }) };
            let live = self.live.get(&c.id).unwrap_or(&empty);
            draw::draw_symbol(&pen, c.kind, &c.params, live);
            draw::draw_labels(&painter, c, o, s);
            if selected {
                let r = Self::comp_screen_rect(c, Pos2::ZERO + (origin - Pos2::ZERO), s).expand(3.0);
                dashed_rect(&painter, r, SELECT);
            } else if hover_comp == Some(c.id) && self.tool == Tool::Select && hover_pin.is_none() {
                let r = Self::comp_screen_rect(c, origin, s).expand(3.0);
                painter.rect_stroke(r, 2.0, Stroke::new(1.0, Color32::from_rgba_unmultiplied(0, 140, 255, 90)));
            }
        }
        // hovered pin marker
        if let Some(p) = hover_pin {
            if matches!(self.drag, Drag::None) {
                painter.circle_stroke(to_screen(p), (0.45 * s).max(4.0), Stroke::new(1.5, Color32::from_rgb(230, 40, 40)));
            }
        }

        // ---- previews
        if let (Tool::Place(kind), Some(sp)) = (self.tool, snapped) {
            if resp.hovered() {
                let pen = Pen { painter: &painter, origin: to_screen(sp), s, rot: self.place_rot, stroke: Stroke::new(stroke_w, Color32::from_rgba_unmultiplied(28, 32, 110, 120)) };
                draw::draw_symbol(&pen, kind, &kind.default_params(), &empty);
            }
        }
        if let Some(pts) = &self.wiring {
            let target = hover_pin.or(snapped).unwrap_or(*pts.last().unwrap());
            let mut all = pts.clone();
            let last = *all.last().unwrap();
            if last.x != target.x && last.y != target.y {
                all.push(GP::new(target.x, last.y));
            }
            all.push(target);
            let v: Vec<Pos2> = all.iter().map(|p| to_screen(*p)).collect();
            painter.add(Shape::line(v, Stroke::new(wire_w, Color32::from_rgba_unmultiplied(210, 30, 30, 170))));
            painter.circle_filled(to_screen(target), 3.0, Color32::from_rgb(210, 30, 30));
        }
        if let (Drag::Band { start }, Some(p)) = (&self.drag, ptr) {
            let r = Rect::from_two_pos(*start, p);
            painter.rect(r, 0.0, Color32::from_rgba_unmultiplied(0, 140, 255, 25), Stroke::new(1.0, SELECT));
        }

        // title block in the corner of the sheet
        let title = if self.circuit.title.is_empty() { "Untitled" } else { &self.circuit.title };
        let tb = Rect::from_min_size(rect.right_bottom() - vec2(240.0, 46.0), vec2(232.0, 38.0));
        painter.rect(tb, 0.0, Color32::from_rgba_unmultiplied(255, 255, 255, 230), Stroke::new(1.0, Color32::from_gray(150)));
        painter.text(tb.left_top() + vec2(6.0, 4.0), Align2::LEFT_TOP, title, FontId::proportional(13.0), Color32::from_gray(30));
        painter.text(
            tb.left_bottom() + vec2(6.0, -4.0),
            Align2::LEFT_BOTTOM,
            format!("{} parts · {} wires · zoom {:.0}%", self.circuit.components.len(), self.circuit.wires.len(), self.zoom * 100.0 / 1.6),
            FontId::proportional(11.0),
            Color32::from_gray(90),
        );
        if self.running {
            let badge = Rect::from_min_size(rect.left_top() + vec2(8.0, 8.0), vec2(150.0, 22.0));
            let col = if self.paused { Color32::from_rgb(220, 160, 0) } else { Color32::from_rgb(30, 160, 60) };
            painter.rect_filled(badge, 4.0, col);
            painter.text(badge.center(), Align2::CENTER_CENTER, if self.paused { "SIMULATION PAUSED" } else { "SIMULATING" }, FontId::proportional(12.0), Color32::WHITE);
        }
    }

    fn on_press(&mut self, sp: GP, hover_pin: Option<GP>, hover_comp: Option<u64>, hover_wire: Option<u64>, shift: bool, ptr: Pos2) {
        if let Tool::Place(kind) = self.tool {
            self.edit_stop();
            self.checkpoint();
            let id = self.circuit.add(kind, sp, self.place_rot);
            self.selection.clear();
            self.selection.insert(Sel::Comp(id));
            if !shift {
                self.tool = Tool::Select;
            }
            return;
        }
        if let Some(pts) = &mut self.wiring {
            let target = hover_pin.unwrap_or(sp);
            let last = *pts.last().unwrap();
            if target == last {
                return;
            }
            if last.x != target.x && last.y != target.y {
                pts.push(GP::new(target.x, last.y));
            }
            pts.push(target);
            let start = pts[0];
            let ends_on_wire = self.circuit.wires.iter().any(|w| w.points.windows(2).any(|s| sim::on_segment(target, s[0], s[1])));
            let ends_on_pin = hover_pin.is_some() && target != start;
            if ends_on_pin || ends_on_wire {
                self.finish_wire();
            }
            return;
        }
        if self.tool == Tool::Wire {
            self.wiring = Some(vec![hover_pin.unwrap_or(sp)]);
            return;
        }
        // select tool
        if let Some(p) = hover_pin {
            self.wiring = Some(vec![p]);
            return;
        }
        if let Some(id) = hover_comp {
            // interactive click on a switch while running
            if self.running {
                if let Some(c) = self.circuit.comp_mut(id) {
                    if c.kind == Kind::Switch {
                        c.params.closed = !c.params.closed;
                    }
                }
            }
            let s = Sel::Comp(id);
            if shift {
                if !self.selection.remove(&s) {
                    self.selection.insert(s);
                }
            } else if !self.selection.contains(&s) {
                self.selection.clear();
                self.selection.insert(s);
            }
            self.drag = Drag::Move { start: sp, delta: GP::new(0, 0), orig: self.circuit.clone() };
            return;
        }
        if let Some(id) = hover_wire {
            let s = Sel::Wire(id);
            if shift {
                if !self.selection.remove(&s) {
                    self.selection.insert(s);
                }
            } else if !self.selection.contains(&s) {
                self.selection.clear();
                self.selection.insert(s);
            }
            self.drag = Drag::Move { start: sp, delta: GP::new(0, 0), orig: self.circuit.clone() };
            return;
        }
        if !shift {
            self.selection.clear();
        }
        self.drag = Drag::Band { start: ptr };
    }

    fn finish_wire(&mut self) {
        if let Some(pts) = self.wiring.take() {
            let pts = simplify(pts);
            if pts.len() >= 2 {
                self.edit_stop();
                self.checkpoint();
                let id = self.circuit.add_wire(pts);
                self.selection.clear();
                let _ = id;
            }
        }
    }

    fn open_props(&mut self, id: u64) {
        if let Some(c) = self.circuit.comp(id) {
            if c.kind.is_instrument() {
                if !self.open_inst.contains(&id) {
                    self.open_inst.push(id);
                }
            } else if c.kind != Kind::Ground {
                self.props = Some(id);
                self.props_orig = Some(self.circuit.clone());
            }
        }
    }

    // ------------------------------------------------------------ panels

    fn menu_bar(&mut self, ui: &mut Ui, ctx: &egui::Context) {
        egui::menu::bar(ui, |ui| {
            ui.menu_button("File", |ui| {
                if ui.button("New                    Ctrl+N").clicked() {
                    self.confirm_new = Some(None);
                    ui.close_menu();
                }
                if ui.button("Open…                  Ctrl+O").clicked() {
                    self.open_file_dlg(false, false);
                    ui.close_menu();
                }
                ui.menu_button("Examples", |ui| {
                    for (i, n) in examples::NAMES.iter().enumerate() {
                        if ui.button(*n).clicked() {
                            self.confirm_new = Some(Some(i));
                            ui.close_menu();
                        }
                    }
                });
                ui.separator();
                if ui.button("Save                   Ctrl+S").clicked() {
                    self.save();
                    ui.close_menu();
                }
                if ui.button("Save as…").clicked() {
                    self.open_file_dlg(true, false);
                    ui.close_menu();
                }
                if ui.button("Export SPICE netlist…").clicked() {
                    self.open_file_dlg(true, true);
                    ui.close_menu();
                }
                ui.separator();
                if ui.button("Quit").clicked() {
                    ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                }
            });
            ui.menu_button("Edit", |ui| {
                if ui.add_enabled(!self.undo.is_empty(), egui::Button::new("Undo              Ctrl+Z")).clicked() {
                    self.do_undo();
                    ui.close_menu();
                }
                if ui.add_enabled(!self.redo.is_empty(), egui::Button::new("Redo              Ctrl+Y")).clicked() {
                    self.do_redo();
                    ui.close_menu();
                }
                ui.separator();
                if ui.button("Cut                 Ctrl+X").clicked() {
                    self.copy_selection();
                    self.delete_selection();
                    ui.close_menu();
                }
                if ui.button("Copy                Ctrl+C").clicked() {
                    self.copy_selection();
                    ui.close_menu();
                }
                if ui.button("Paste               Ctrl+V").clicked() {
                    self.paste();
                    ui.close_menu();
                }
                if ui.button("Delete              Del").clicked() {
                    self.delete_selection();
                    ui.close_menu();
                }
                if ui.button("Select all          Ctrl+A").clicked() {
                    self.selection = self.circuit.components.iter().map(|c| Sel::Comp(c.id)).chain(self.circuit.wires.iter().map(|w| Sel::Wire(w.id))).collect();
                    ui.close_menu();
                }
                ui.separator();
                if ui.button("Rotate 90° clockwise          Ctrl+R").clicked() {
                    self.rotate_selection(false);
                    ui.close_menu();
                }
                if ui.button("Rotate 90° counter-clockwise").clicked() {
                    self.rotate_selection(true);
                    ui.close_menu();
                }
                if ui.button("Properties…").clicked() {
                    if let Some(id) = self.selected_comps().into_iter().next() {
                        self.open_props(id);
                    }
                    ui.close_menu();
                }
                ui.separator();
                if ui.button("Circuit title…").clicked() {
                    self.props = Some(0);
                    self.props_orig = Some(self.circuit.clone());
                    ui.close_menu();
                }
            });
            ui.menu_button("View", |ui| {
                if ui.button("Zoom in        Ctrl++").clicked() {
                    self.zoom = (self.zoom * 1.25).min(8.0);
                }
                if ui.button("Zoom out       Ctrl+−").clicked() {
                    self.zoom = (self.zoom / 1.25).max(0.25);
                }
                if ui.button("Zoom to fit    F7").clicked() {
                    self.need_fit = true;
                }
                ui.separator();
                ui.checkbox(&mut self.show_grid, "Show grid");
                ui.checkbox(&mut self.show_nets, "Show net numbers (while simulating)");
                ui.checkbox(&mut self.show_parts, "Parts bin");
                ui.checkbox(&mut self.show_sheet, "Spreadsheet view");
                if ui.button("Grapher").clicked() {
                    self.grapher_open = true;
                    ui.close_menu();
                }
            });
            ui.menu_button("Place", |ui| {
                for (group, kinds) in PART_GROUPS {
                    ui.menu_button(*group, |ui| {
                        for k in kinds.iter() {
                            if ui.button(k.name()).clicked() {
                                self.tool = Tool::Place(*k);
                                self.place_rot = 0;
                                ui.close_menu();
                            }
                        }
                    });
                }
                ui.menu_button("Instruments", |ui| {
                    for k in [Kind::Multimeter, Kind::FuncGen, Kind::Oscilloscope] {
                        if ui.button(k.name()).clicked() {
                            self.tool = Tool::Place(k);
                            self.place_rot = 0;
                            ui.close_menu();
                        }
                    }
                });
                ui.separator();
                if ui.button("Wire                W").clicked() {
                    self.tool = Tool::Wire;
                    ui.close_menu();
                }
            });
            ui.menu_button("Simulate", |ui| {
                if ui.button(if self.running { "Stop                F5" } else { "Run                 F5" }).clicked() {
                    self.toggle_run();
                    ui.close_menu();
                }
                if ui.add_enabled(self.running, egui::Button::new(if self.paused { "Resume              F6" } else { "Pause               F6" })).clicked() {
                    self.paused = !self.paused;
                    ui.close_menu();
                }
                ui.separator();
                if ui.button("Analyses and simulation…").clicked() {
                    self.analysis_open = true;
                    ui.close_menu();
                }
                for (k, n) in [(AnalysisKind::DcOp, "DC operating point"), (AnalysisKind::Ac, "AC sweep"), (AnalysisKind::Transient, "Transient"), (AnalysisKind::DcSweep, "DC sweep")] {
                    if ui.button(format!("    {}", n)).clicked() {
                        self.cfg.sel = k;
                        self.analysis_open = true;
                        ui.close_menu();
                    }
                }
                ui.separator();
                if ui.button("Interactive simulation settings…").clicked() {
                    self.cfg.sel = AnalysisKind::Interactive;
                    self.analysis_open = true;
                    ui.close_menu();
                }
            });
            ui.menu_button("Tools", |ui| {
                if ui.button("Electrical rules check").clicked() {
                    self.bottom_tab = BottomTab::Erc;
                    self.show_sheet = true;
                    ui.close_menu();
                }
                if ui.button("Parts list").clicked() {
                    self.bottom_tab = BottomTab::Components;
                    self.show_sheet = true;
                    ui.close_menu();
                }
            });
            ui.menu_button("Help", |ui| {
                if ui.button("Quick guide").clicked() {
                    self.help_open = true;
                    ui.close_menu();
                }
                if ui.button("About Circuit Bench").clicked() {
                    self.about_open = true;
                    ui.close_menu();
                }
            });
        });
    }

    fn toolbar(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            ui.spacing_mut().button_padding = vec2(8.0, 4.0);
            if ui.button("New").on_hover_text("New circuit (Ctrl+N)").clicked() {
                self.confirm_new = Some(None);
            }
            if ui.button("Open").on_hover_text("Open a saved circuit (Ctrl+O)").clicked() {
                self.open_file_dlg(false, false);
            }
            if ui.button("Save").on_hover_text("Save (Ctrl+S)").clicked() {
                self.save();
            }
            ui.separator();
            if ui.add_enabled(!self.undo.is_empty(), egui::Button::new("Undo")).clicked() {
                self.do_undo();
            }
            if ui.add_enabled(!self.redo.is_empty(), egui::Button::new("Redo")).clicked() {
                self.do_redo();
            }
            ui.separator();
            let has_sel = !self.selection.is_empty();
            if ui.add_enabled(has_sel, egui::Button::new("Copy")).clicked() {
                self.copy_selection();
            }
            if ui.add_enabled(!self.clipboard.0.is_empty() || !self.clipboard.1.is_empty(), egui::Button::new("Paste")).clicked() {
                self.paste();
            }
            if ui.add_enabled(has_sel, egui::Button::new("Rotate")).on_hover_text("Rotate 90° (Ctrl+R)").clicked() {
                self.rotate_selection(false);
            }
            if ui.add_enabled(has_sel, egui::Button::new("Delete")).clicked() {
                self.delete_selection();
            }
            ui.separator();
            if ui.button("Zoom +").clicked() {
                self.zoom = (self.zoom * 1.25).min(8.0);
            }
            if ui.button("Zoom −").clicked() {
                self.zoom = (self.zoom / 1.25).max(0.25);
            }
            if ui.button("Fit").on_hover_text("Zoom to fit (F7)").clicked() {
                self.need_fit = true;
            }
            ui.separator();
            if ui.add(egui::Button::new("Select").selected(self.tool == Tool::Select)).clicked() {
                self.tool = Tool::Select;
                self.wiring = None;
            }
            if ui.add(egui::Button::new("Wire").selected(self.tool == Tool::Wire)).on_hover_text("Draw wires (W). You can also click any pin to start a wire.").clicked() {
                self.tool = if self.tool == Tool::Wire { Tool::Select } else { Tool::Wire };
            }
            ui.separator();
            if ui.button("Analyses…").clicked() {
                self.analysis_open = true;
            }
            if ui.button("Grapher").clicked() {
                self.grapher_open = true;
            }

            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                // Stop, pause, run (right-to-left)
                if sim_button(ui, SimIcon::Stop, self.running, "Stop simulation").clicked() && self.running {
                    self.stop_sim();
                    self.log("Simulation stopped.");
                }
                if sim_button(ui, SimIcon::Pause, self.running && self.paused, "Pause / resume (F6)").clicked() && self.running {
                    self.paused = !self.paused;
                }
                if sim_button(ui, SimIcon::Run, self.running && !self.paused, "Run interactive simulation (F5)").clicked() {
                    if !self.running {
                        self.start_sim();
                        if self.running {
                            self.log("Interactive simulation running.");
                        }
                    } else {
                        self.paused = false;
                    }
                }
                ui.label(RichText::new("Simulate").strong());
            });
        });
    }

    fn parts_panel(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.heading("Parts bin");
        ui.label(RichText::new("Click a part, then click the sheet to place it.").small().weak());
        ui.add_space(2.0);
        egui::ScrollArea::vertical().id_source("parts_scroll").max_height(ui.available_height() * 0.62).show(ui, |ui| {
            for (group, kinds) in PART_GROUPS {
                egui::CollapsingHeader::new(RichText::new(*group).strong()).default_open(true).show(ui, |ui| {
                    for k in kinds.iter() {
                        if part_row(ui, *k, self.tool == Tool::Place(*k)).clicked() {
                            self.tool = Tool::Place(*k);
                            self.place_rot = 0;
                            self.wiring = None;
                        }
                    }
                });
            }
        });
        ui.separator();
        ui.label(RichText::new("Design toolbox").strong());
        egui::ScrollArea::vertical().id_source("toolbox_scroll").show(ui, |ui| {
            ui.label(format!("▾ {}", if self.circuit.title.is_empty() { "Untitled" } else { &self.circuit.title }));
            let mut items: Vec<(String, u64, Kind)> = self.circuit.components.iter().filter(|c| c.kind != Kind::Ground).map(|c| (c.refdes.clone(), c.id, c.kind)).collect();
            items.sort_by(|a, b| natural_key(&a.0).cmp(&natural_key(&b.0)));
            for (name, id, kind) in items {
                let sel = self.selection.contains(&Sel::Comp(id));
                let r = ui.selectable_label(sel, format!("    {}  —  {}", name, kind.name()));
                if r.clicked() {
                    self.selection.clear();
                    self.selection.insert(Sel::Comp(id));
                }
                if r.double_clicked() {
                    self.open_props(id);
                }
            }
        });
    }

    fn right_panel(&mut self, ui: &mut Ui) {
        ui.add_space(4.0);
        ui.heading("Instruments");
        ui.label(RichText::new("Place, wire up, then double-click to open its panel.").small().weak());
        for k in [Kind::Multimeter, Kind::FuncGen, Kind::Oscilloscope] {
            if part_row(ui, k, self.tool == Tool::Place(k)).clicked() {
                self.tool = Tool::Place(k);
                self.place_rot = 0;
            }
        }
        let insts: Vec<(u64, String)> = self.circuit.components.iter().filter(|c| c.kind.is_instrument()).map(|c| (c.id, c.refdes.clone())).collect();
        if !insts.is_empty() {
            ui.add_space(4.0);
            ui.label(RichText::new("Open panel").small());
            ui.horizontal_wrapped(|ui| {
                for (id, name) in insts {
                    if ui.small_button(name).clicked() && !self.open_inst.contains(&id) {
                        self.open_inst.push(id);
                    }
                }
            });
        }
        ui.separator();
        ui.heading("Selection");
        let comps = self.selected_comps();
        if comps.len() == 1 {
            let id = *comps.iter().next().unwrap();
            if let Some(c) = self.circuit.comp(id).cloned() {
                ui.label(RichText::new(format!("{}  ({})", c.refdes, c.kind.name())).strong());
                let v = c.value_label();
                if !v.is_empty() {
                    ui.label(v);
                }
                if let Some(l) = self.live.get(&id).and_then(|l| l.reading.clone()) {
                    ui.label(RichText::new(l).monospace().color(Color32::from_rgb(0, 110, 40)));
                }
                if let Some(sim) = &self.sim {
                    if let Some(ci) = self.circuit.components.iter().position(|x| x.id == id) {
                        let names: Vec<&str> = c.kind.pins().iter().map(|p| p.2).collect();
                        for (k, n) in sim.nl.comp_nets[ci].iter().enumerate() {
                            ui.label(RichText::new(format!("pin {} → net {}  {}", names[k], n, fmt_reading(sim.v(*n), "V"))).small().monospace());
                        }
                        if !matches!(c.kind, Kind::Ground | Kind::Probe | Kind::Oscilloscope | Kind::FuncGen | Kind::Multimeter | Kind::Potentiometer) {
                            ui.label(RichText::new(format!("I = {}", fmt_reading(sim.comp_current(ci), "A"))).small().monospace());
                        }
                    }
                }
                ui.horizontal(|ui| {
                    if ui.button("Properties…").clicked() {
                        self.open_props(id);
                    }
                    if ui.button("⟳").on_hover_text("Rotate").clicked() {
                        self.rotate_selection(false);
                    }
                });
            }
        } else if self.selection.is_empty() {
            ui.label(RichText::new("Nothing selected").weak());
        } else {
            ui.label(format!("{} items selected", self.selection.len()));
        }
        if !self.hover_info.is_empty() {
            ui.separator();
            ui.label(RichText::new(&self.hover_info).monospace().color(Color32::from_rgb(0, 90, 160)));
        }
    }

    fn spreadsheet(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            ui.selectable_value(&mut self.bottom_tab, BottomTab::Results, "Results");
            ui.selectable_value(&mut self.bottom_tab, BottomTab::Nets, "Nets");
            ui.selectable_value(&mut self.bottom_tab, BottomTab::Components, "Components");
            ui.selectable_value(&mut self.bottom_tab, BottomTab::Erc, "Electrical rules check");
            if self.bottom_tab == BottomTab::Results {
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if ui.small_button("Clear").clicked() {
                        self.messages.clear();
                    }
                });
            }
        });
        ui.separator();
        egui::ScrollArea::vertical().auto_shrink([false, false]).stick_to_bottom(self.bottom_tab == BottomTab::Results).show(ui, |ui| match self.bottom_tab {
            BottomTab::Results => {
                for m in &self.messages {
                    ui.label(RichText::new(m).monospace().size(12.0));
                }
            }
            BottomTab::Nets => {
                let nl = sim::build_netlist(&self.circuit);
                let mut pins: Vec<Vec<String>> = vec![Vec::new(); nl.n_nets];
                for (ci, c) in self.circuit.components.iter().enumerate() {
                    for (k, n) in nl.comp_nets[ci].iter().enumerate() {
                        if c.kind != Kind::Ground {
                            pins[*n].push(format!("{}.{}", c.refdes, c.kind.pins()[k].2));
                        }
                    }
                }
                egui::Grid::new("nets").striped(true).num_columns(3).show(ui, |ui| {
                    ui.strong("Net");
                    ui.strong("Voltage");
                    ui.strong("Connected pins");
                    ui.end_row();
                    for (n, p) in pins.iter().enumerate() {
                        ui.label(if n == 0 { "0 (ground)".to_string() } else { n.to_string() });
                        let v = if !nl.has_ground && n == 0 { "-".into() } else { self.sim.as_ref().map(|s| fmt_reading(s.v(n), "V")).unwrap_or_else(|| "—".into()) };
                        ui.monospace(v);
                        ui.label(p.join(", "));
                        ui.end_row();
                    }
                });
            }
            BottomTab::Components => {
                egui::Grid::new("comps").striped(true).num_columns(4).show(ui, |ui| {
                    ui.strong("RefDes");
                    ui.strong("Part");
                    ui.strong("Value");
                    ui.strong("Position");
                    ui.end_row();
                    let mut v: Vec<&Component> = self.circuit.components.iter().filter(|c| c.kind != Kind::Ground).collect();
                    v.sort_by(|a, b| natural_key(&a.refdes).cmp(&natural_key(&b.refdes)));
                    for c in v {
                        ui.label(&c.refdes);
                        ui.label(c.kind.name());
                        ui.label(c.value_label());
                        ui.label(format!("({}, {})  {}°", c.pos.x, c.pos.y, c.rot as u32 * 90));
                        ui.end_row();
                    }
                });
            }
            BottomTab::Erc => {
                let issues = erc(&self.circuit);
                if issues.is_empty() {
                    ui.label(RichText::new("✔ No problems found.").color(Color32::from_rgb(0, 130, 40)));
                }
                for s in issues {
                    ui.label(RichText::new(format!("⚠ {}", s)).color(Color32::from_rgb(170, 90, 0)));
                }
            }
        });
    }

    fn status_bar(&mut self, ui: &mut Ui) {
        ui.horizontal(|ui| {
            let hint = if self.wiring.is_some() {
                "Click to add a corner · click a pin or wire to connect · double-click to end · Esc cancels".to_string()
            } else {
                match self.tool {
                    Tool::Place(k) => format!("Click to place a {} · R rotates · hold Shift to place several · Esc cancels", k.name().to_lowercase()),
                    Tool::Wire => "Wire mode: click anywhere to start a wire · W or Esc to leave".into(),
                    Tool::Select => {
                        if self.running {
                            "Simulating · press a switch's key (or click it) to toggle · A / Shift+A turn potentiometers · F5 stops".into()
                        } else {
                            "Click to select · drag to move · click a pin to wire · double-click to edit · Ctrl+R rotates · Del deletes".into()
                        }
                    }
                }
            };
            ui.label(RichText::new(hint).small());
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if let Some(sim) = &self.sim {
                    ui.label(RichText::new(format!("Tran: {}   step {}   {} steps/frame", fmt_si(sim.t, "s"), fmt_si(self.h_used, "s"), self.steps_last_frame)).monospace().small());
                } else if let Some(e) = &self.sim_error {
                    ui.label(RichText::new(e).small().color(Color32::from_rgb(190, 40, 40)));
                } else {
                    ui.label(RichText::new("Simulation stopped").small());
                }
                if self.dirty {
                    ui.label(RichText::new("● modified").small().color(Color32::from_rgb(170, 90, 0)));
                }
            });
        });
    }

    // ------------------------------------------------------------ windows

    fn props_window(&mut self, ctx: &egui::Context) {
        let Some(id) = self.props else {
            return;
        };
        let mut open = true;
        let mut close = false;
        let mut cancel = false;
        if id == 0 {
            egui::Window::new("Circuit title").collapsible(false).resizable(false).open(&mut open).show(ctx, |ui| {
                ui.text_edit_singleline(&mut self.circuit.title);
                if ui.button("OK").clicked() {
                    close = true;
                }
            });
        } else {
            let Some(idx) = self.circuit.components.iter().position(|c| c.id == id) else {
                self.props = None;
                return;
            };
            let title = format!("{} — {}", self.circuit.components[idx].kind.name(), self.circuit.components[idx].refdes);
            egui::Window::new(title).id(Id::new("props_win")).collapsible(false).resizable(false).default_width(320.0).open(&mut open).show(ctx, |ui| {
                let c = &mut self.circuit.components[idx];
                let pid = Id::new(("prop", id));
                egui::Grid::new("props_grid").num_columns(2).spacing([12.0, 6.0]).show(ui, |ui| {
                    ui.label("RefDes");
                    ui.add(egui::TextEdit::singleline(&mut c.refdes).desired_width(150.0));
                    ui.end_row();
                    let p = &mut c.params;
                    match c.kind {
                        Kind::Resistor => {
                            ui.label("Resistance");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "Ω", 150.0);
                            ui.end_row();
                        }
                        Kind::Capacitor => {
                            ui.label("Capacitance");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "F", 150.0);
                            ui.end_row();
                            ui.label("Initial voltage");
                            instruments::si_field(ui, pid.with(2), &mut p.ic, "V", 150.0);
                            ui.end_row();
                        }
                        Kind::Inductor => {
                            ui.label("Inductance");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "H", 150.0);
                            ui.end_row();
                            ui.label("Initial current");
                            instruments::si_field(ui, pid.with(2), &mut p.ic, "A", 150.0);
                            ui.end_row();
                        }
                        Kind::Potentiometer => {
                            ui.label("Resistance");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "Ω", 150.0);
                            ui.end_row();
                            ui.label("Setting");
                            ui.add(egui::Slider::new(&mut p.setting, 0.0..=100.0).suffix(" %"));
                            ui.end_row();
                            ui.label("Increment");
                            ui.add(egui::DragValue::new(&mut p.increment).suffix(" %").clamp_range(0.1..=50.0));
                            ui.end_row();
                            ui.label("Key");
                            key_field(ui, &mut p.key);
                            ui.end_row();
                        }
                        Kind::DcVoltage => {
                            ui.label("Voltage");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "V", 150.0);
                            ui.end_row();
                        }
                        Kind::DcCurrent => {
                            ui.label("Current");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "A", 150.0);
                            ui.end_row();
                        }
                        Kind::AcVoltage => {
                            ui.label("Amplitude (peak)");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "V", 150.0);
                            ui.end_row();
                            ui.label("Frequency");
                            instruments::si_field(ui, pid.with(2), &mut p.freq, "Hz", 150.0);
                            ui.end_row();
                            ui.label("Phase");
                            ui.add(egui::DragValue::new(&mut p.phase).suffix("°").clamp_range(-360.0..=360.0));
                            ui.end_row();
                            ui.label("DC offset");
                            instruments::si_field(ui, pid.with(3), &mut p.offset, "V", 150.0);
                            ui.end_row();
                        }
                        Kind::Diode => {
                            ui.label("Saturation current (Is)");
                            instruments::si_field(ui, pid.with(1), &mut p.is, "A", 150.0);
                            ui.end_row();
                            ui.label("Emission coefficient (N)");
                            ui.add(egui::DragValue::new(&mut p.n).speed(0.01).clamp_range(0.5..=4.0));
                            ui.end_row();
                        }
                        Kind::Zener => {
                            ui.label("Zener voltage");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "V", 150.0);
                            ui.end_row();
                        }
                        Kind::Led => {
                            ui.label("Colour");
                            egui::ComboBox::from_id_source("ledcol").selected_text(p.led.name()).show_ui(ui, |ui| {
                                for c in LedColor::ALL {
                                    ui.selectable_value(&mut p.led, c, format!("{}  (≈{} V)", c.name(), c.forward_voltage()));
                                }
                            });
                            ui.end_row();
                        }
                        Kind::Switch => {
                            ui.label("Key");
                            key_field(ui, &mut p.key);
                            ui.end_row();
                            ui.label("State");
                            ui.checkbox(&mut p.closed, "Closed");
                            ui.end_row();
                        }
                        Kind::Lamp => {
                            ui.label("Rated voltage");
                            instruments::si_field(ui, pid.with(1), &mut p.value, "V", 150.0);
                            ui.end_row();
                            ui.label("Rated power");
                            instruments::si_field(ui, pid.with(2), &mut p.power, "W", 150.0);
                            ui.end_row();
                        }
                        Kind::Voltmeter | Kind::Ammeter => {
                            ui.label("Mode");
                            ui.horizontal(|ui| {
                                ui.selectable_value(&mut p.ac, false, "DC");
                                ui.selectable_value(&mut p.ac, true, "AC (RMS)");
                            });
                            ui.end_row();
                        }
                        _ => {}
                    }
                    ui.label("Rotation");
                    ui.label(format!("{}°", c.rot as u32 * 90));
                    ui.end_row();
                });
                ui.add_space(6.0);
                ui.horizontal(|ui| {
                    if ui.button("  OK  ").clicked() {
                        close = true;
                    }
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                });
                ui.label(RichText::new("Values accept prefixes: p n u m k M (e.g. 4.7k, 100n, 2.2m).").small().weak());
            });
        }
        if cancel {
            if let Some(o) = self.props_orig.take() {
                self.circuit = o;
            }
            self.props = None;
        } else if close || !open {
            if let Some(o) = self.props_orig.take() {
                let changed = serde_json::to_string(&o).ok() != serde_json::to_string(&self.circuit).ok();
                if changed {
                    self.push_undo(o);
                }
            }
            self.props = None;
        }
    }

    fn wire_window(&mut self, ctx: &egui::Context) {
        let Some(id) = self.wire_props else {
            return;
        };
        let Some(idx) = self.circuit.wires.iter().position(|w| w.id == id) else {
            self.wire_props = None;
            return;
        };
        let mut open = true;
        let mut delete = false;
        egui::Window::new("Wire").collapsible(false).resizable(false).open(&mut open).show(ctx, |ui| {
            ui.label("Colour (also used for oscilloscope traces):");
            ui.horizontal(|ui| {
                for c in WireColor::ALL {
                    let [r, g, b] = c.rgb();
                    let sel = self.circuit.wires[idx].color == c;
                    let btn = egui::Button::new(RichText::new("■").color(Color32::from_rgb(r, g, b)).size(20.0)).selected(sel);
                    if ui.add(btn).on_hover_text(c.name()).clicked() {
                        self.circuit.wires[idx].color = c;
                        self.dirty = true;
                    }
                }
            });
            if ui.button("Delete wire").clicked() {
                delete = true;
            }
        });
        if delete {
            self.edit_stop();
            self.checkpoint();
            self.circuit.wires.remove(idx);
            self.wire_props = None;
        } else if !open {
            self.wire_props = None;
        }
    }

    fn instrument_windows(&mut self, ctx: &egui::Context) {
        let ids = self.open_inst.clone();
        let mut screen = ctx.screen_rect();
        screen.min.y += 70.0;
        for (n, id) in ids.iter().enumerate() {
            let Some(idx) = self.circuit.components.iter().position(|c| c.id == *id) else {
                continue;
            };
            let kind = self.circuit.components[idx].kind;
            let refdes = self.circuit.components[idx].refdes.clone();
            let mut open = true;
            let default_pos = match kind {
                Kind::Oscilloscope => pos2(screen.right() - 900.0, screen.top() + 40.0 + n as f32 * 30.0),
                _ => pos2(screen.right() - 640.0 + n as f32 * 30.0, screen.top() + 60.0 + n as f32 * 30.0),
            };
            let title = format!("{} — {}", kind.name(), refdes);
            let mut structural = false;
            egui::Window::new(title)
                .id(Id::new(("inst", *id)))
                .default_pos(default_pos)
                .resizable(kind == Kind::Oscilloscope)
                .default_width(if kind == Kind::Oscilloscope { 640.0 } else { 280.0 })
                .open(&mut open)
                .show(ctx, |ui| match kind {
                    Kind::Oscilloscope => {
                        let colors = scope_colors(&self.circuit, idx);
                        let sc = self.scopes.entry(*id).or_default();
                        instruments::scope_panel(ui, sc, colors);
                    }
                    Kind::Multimeter => {
                        let reading = self.meters.get(id).map(|m| multimeter_text(&self.circuit.components[idx], m)).unwrap_or_else(|| "----".into());
                        let p = &mut self.circuit.components[idx].params;
                        if instruments::multimeter_panel(ui, p, &reading) {
                            structural = true;
                        }
                    }
                    Kind::FuncGen => {
                        let p = &mut self.circuit.components[idx].params;
                        if instruments::funcgen_panel(ui, Id::new(("fg", *id)), p) {
                            self.dirty = true;
                        }
                        instruments::wave_preview(ui, p);
                    }
                    _ => {}
                });
            if structural {
                self.dirty = true;
                self.meters.remove(id);
            }
            if !open {
                self.open_inst.retain(|x| x != id);
            }
        }
    }

    fn analysis_window(&mut self, ctx: &egui::Context) {
