                        }
                    }
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        let label = if self.cfg.sel == AnalysisKind::Interactive { "Run interactive" } else { "Run" };
                        if ui.add(egui::Button::new(RichText::new(label).strong()).min_size(vec2(90.0, 26.0))).clicked() {
                            run = true;
                        }
                    });
                });
            });
        });
        if !open {
            self.analysis_open = false;
        }
        if run {
            self.run_analysis();
        }
    }

    fn chosen_vars(&self) -> Vec<Var> {
        let nl = sim::build_netlist(&self.circuit);
        let vars = sim::all_vars(&self.circuit, &nl);
        let chosen: Vec<Var> = vars.iter().filter(|v| self.cfg.out_vars.contains(&sim::var_name(&self.circuit, v))).cloned().collect();
        if chosen.is_empty() {
            vars.into_iter().filter(|v| matches!(v, Var::Node(_))).collect()
        } else {
            chosen
        }
    }

    fn run_analysis(&mut self) {
        let title = if self.circuit.title.is_empty() { "Untitled".to_string() } else { self.circuit.title.clone() };
        let vars = self.chosen_vars();
        let res: Result<GraphTab, String> = match self.cfg.sel {
            AnalysisKind::Interactive => {
                self.analysis_open = false;
                if self.running {
                    self.stop_sim();
                }
                self.start_sim();
                return;
            }
            AnalysisKind::DcOp => sim::run_dc_op(&self.circuit).map(|r| GraphTab::Op { title: format!("{} — DC operating point", title), rows: r.rows }),
            AnalysisKind::Ac => sim::run_ac(&self.circuit, self.cfg.ac_fstart, self.cfg.ac_fstop, self.cfg.ac_ppd, &vars).map(|s| GraphTab::Ac { title: format!("{} — AC sweep", title), series: s }),
            AnalysisKind::Transient => {
                if self.cfg.tr_step <= 0.0 || self.cfg.tr_stop <= 0.0 {
                    Err("End time and time step must be greater than zero.".into())
                } else {
                    sim::run_transient(&self.circuit, self.cfg.tr_stop, self.cfg.tr_step, self.cfg.tr_use_op, &vars)
                        .map(|s| GraphTab::Xy { title: format!("{} — Transient", title), xlabel: "Time".into(), xunit: "s", series: s })
                }
            }
            AnalysisKind::DcSweep => {
                let idx = self.cfg.dc_src.and_then(|id| self.circuit.components.iter().position(|c| c.id == id));
                match idx {
                    None => Err("Choose a DC source to sweep.".into()),
                    Some(i) => {
                        let unit = if self.circuit.components[i].kind == Kind::DcCurrent { "A" } else { "V" };
                        let name = self.circuit.components[i].refdes.clone();
                        sim::run_dc_sweep(&self.circuit, i, self.cfg.dc_start, self.cfg.dc_stop, self.cfg.dc_incr, &vars)
                            .map(|s| GraphTab::Xy { title: format!("{} — DC sweep of {}", title, name), xlabel: name.clone(), xunit: unit, series: s })
                    }
                }
            }
        };
        match res {
            Ok(tab) => {
                self.log(format!("Analysis finished: {}", tab.title()));
                if let GraphTab::Op { rows, .. } = &tab {
                    for (n, v, u) in rows {
                        self.messages.push(format!("    {:<12} {}", n, fmt_reading(*v, u)));
                    }
                }
                self.graphs.push(tab);
                self.graph_sel = self.graphs.len() - 1;
                self.grapher_open = true;
            }
            Err(e) => {
                self.log(format!("Analysis failed: {}", e));
                self.bottom_tab = BottomTab::Results;
            }
        }
    }

    fn grapher_window(&mut self, ctx: &egui::Context) {
        if !self.grapher_open {
            return;
        }
        let mut open = true;
        let mut remove: Option<usize> = None;
        let mut export: Option<usize> = None;
        egui::Window::new("Grapher").default_size([720.0, 480.0]).default_pos(pos2(260.0, 120.0)).open(&mut open).show(ctx, |ui| {
            if self.graphs.is_empty() {
                ui.label("No results yet. Use Simulate ▸ Analyses and simulation… to run an analysis.");
                return;
            }
            ui.horizontal_wrapped(|ui| {
                for (i, g) in self.graphs.iter().enumerate() {
                    ui.selectable_value(&mut self.graph_sel, i, g.title());
                }
            });
            ui.horizontal(|ui| {
                if ui.button("Export CSV").clicked() {
                    export = Some(self.graph_sel);
                }
                if ui.button("Close tab").clicked() {
                    remove = Some(self.graph_sel);
                }
            });
            ui.separator();
            let sel = self.graph_sel.min(self.graphs.len() - 1);
            match &self.graphs[sel] {
                GraphTab::Op { rows, .. } => {
                    egui::ScrollArea::vertical().show(ui, |ui| {
                        egui::Grid::new("opgrid").striped(true).num_columns(2).min_col_width(140.0).show(ui, |ui| {
                            ui.strong("Variable");
                            ui.strong("Operating point value");
                            ui.end_row();
                            for (n, v, u) in rows {
                                ui.monospace(n);
                                ui.monospace(fmt_reading(*v, u));
                                ui.end_row();
                            }
                        });
                    });
                }
                GraphTab::Xy { xlabel, xunit, series, .. } => {
                    let xu = *xunit;
                    let plot = egui_plot::Plot::new(("xy", sel))
                        .legend(egui_plot::Legend::default())
                        .x_axis_label(format!("{} ({})", xlabel, xu))
                        .x_axis_formatter(move |m, _, _| fmt_si(m.value, xu));
                    plot.show(ui, |pu| {
                        for (k, s) in series.iter().enumerate() {
                            pu.line(egui_plot::Line::new(egui_plot::PlotPoints::from(s.pts.clone())).name(&s.name).color(palette(k)).width(1.6));
                        }
                    });
                }
                GraphTab::Ac { series, .. } => {
                    let h = (ui.available_height() - 10.0) / 2.0;
                    let fmt = |m: egui_plot::GridMark, _: usize, _: &std::ops::RangeInclusive<f64>| {
                        if (m.value - m.value.round()).abs() < 1e-6 {
                            fmt_si(10f64.powf(m.value), "Hz")
                        } else {
                            String::new()
                        }
                    };
                    egui_plot::Plot::new(("acm", sel))
                        .height(h)
                        .legend(egui_plot::Legend::default())
                        .y_axis_label("Magnitude (dB)")
                        .x_axis_formatter(fmt)
                        .link_axis("ac", true, false)
                        .label_formatter(|n, p| format!("{}\n{}  {:.2} dB", n, fmt_si(10f64.powf(p.x), "Hz"), p.y))
                        .show(ui, |pu| {
                            for (k, s) in series.iter().enumerate() {
                                pu.line(egui_plot::Line::new(egui_plot::PlotPoints::from(s.mag.clone())).name(&s.name).color(palette(k)).width(1.6));
                            }
                        });
                    egui_plot::Plot::new(("acp", sel))
                        .height(h)
                        .y_axis_label("Phase (°)")
                        .x_axis_label("Frequency")
                        .x_axis_formatter(fmt)
                        .link_axis("ac", true, false)
                        .label_formatter(|n, p| format!("{}\n{}  {:.1}°", n, fmt_si(10f64.powf(p.x), "Hz"), p.y))
                        .show(ui, |pu| {
                            for (k, s) in series.iter().enumerate() {
                                pu.line(egui_plot::Line::new(egui_plot::PlotPoints::from(s.phase.clone())).name(&s.name).color(palette(k)).width(1.6));
                            }
                        });
                }
            }
        });
        if let Some(i) = export {
            let path = self.file_path.as_ref().and_then(|p| p.parent().map(|d| d.to_path_buf())).unwrap_or_else(default_dir).join(format!("analysis-{}.csv", i + 1));
            match std::fs::write(&path, graph_csv(&self.graphs[i])) {
                Ok(_) => self.log(format!("Exported {}", path.display())),
                Err(e) => self.log(format!("Export failed: {}", e)),
            }
        }
        if let Some(i) = remove {
            self.graphs.remove(i);
            self.graph_sel = self.graph_sel.saturating_sub(1);
        }
        if !open {
            self.grapher_open = false;
        }
    }

    fn file_window(&mut self, ctx: &egui::Context) {
        let Some(dlg) = &mut self.file_dlg else {
            return;
        };
        let mut open = true;
        let mut action: Option<PathBuf> = None;
        let mut cancel = false;
        let title = if dlg.netlist {
            "Export SPICE netlist"
        } else if dlg.save {
            "Save circuit"
        } else {
            "Open circuit"
        };
        egui::Window::new(title).collapsible(false).default_width(480.0).open(&mut open).show(ctx, |ui| {
            ui.horizontal(|ui| {
                if ui.button("⬆ Up").clicked() {
                    if let Some(p) = dlg.dir.parent() {
                        dlg.dir = p.to_path_buf();
                    }
                }
                if ui.button("Documents").clicked() {
                    dlg.dir = default_dir();
                }
                ui.label(RichText::new(dlg.dir.display().to_string()).monospace().small());
            });
            ui.separator();
            egui::ScrollArea::vertical().max_height(260.0).auto_shrink([false, false]).show(ui, |ui| {
                let mut entries: Vec<(bool, String)> = std::fs::read_dir(&dlg.dir)
                    .map(|rd| {
                        rd.filter_map(|e| e.ok())
                            .filter_map(|e| {
                                let name = e.file_name().to_string_lossy().to_string();
                                if name.starts_with('.') {
                                    return None;
                                }
                                let is_dir = e.file_type().map(|t| t.is_dir()).unwrap_or(false);
                                let ext_ok = if dlg.netlist { name.ends_with(".cir") } else { name.ends_with(&format!(".{}", FILE_EXT)) || name.ends_with(".json") };
                                if is_dir || ext_ok {
                                    Some((is_dir, name))
                                } else {
                                    None
                                }
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
                for (is_dir, name) in entries {
                    let label = if is_dir { format!("📁 {}", name) } else { format!("    {}", name) };
                    let r = ui.selectable_label(dlg.name == name, label);
                    if r.clicked() {
                        if is_dir {
                            dlg.dir = dlg.dir.join(&name);
                        } else {
                            dlg.name = name.clone();
                        }
                    }
                    if r.double_clicked() && !is_dir {
                        action = Some(dlg.dir.join(&name));
                    }
                }
            });
            ui.separator();
            ui.horizontal(|ui| {
                ui.label("File name");
                ui.add(egui::TextEdit::singleline(&mut dlg.name).desired_width(280.0));
            });
            if let Some(e) = &dlg.err {
                ui.colored_label(Color32::RED, e);
            }
            ui.horizontal(|ui| {
                let label = if dlg.save { "Save" } else { "Open" };
                if ui.button(label).clicked() && !dlg.name.trim().is_empty() {
                    let mut name = dlg.name.trim().to_string();
                    if dlg.save && !dlg.netlist && !name.contains('.') {
                        name = format!("{}.{}", name, FILE_EXT);
                    }
                    if dlg.netlist && !name.ends_with(".cir") {
                        name = format!("{}.cir", name);
                    }
                    action = Some(dlg.dir.join(name));
                }
                if ui.button("Cancel").clicked() {
                    cancel = true;
                }
            });
        });
        if let Some(p) = action {
            let (save, netlist) = (dlg.save, dlg.netlist);
            self.file_dlg = None;
            if netlist {
                match std::fs::write(&p, spice_netlist(&self.circuit)) {
                    Ok(_) => self.log(format!("Exported netlist {}", p.display())),
                    Err(e) => self.log(format!("Export failed: {}", e)),
                }
            } else if save {
                if let Err(e) = self.save_file(&p) {
                    self.log(format!("Save failed: {}", e));
                }
            } else {
                self.load_file(&p);
            }
            return;
        }
        if cancel || !open {
            self.file_dlg = None;
        }
    }

    fn misc_windows(&mut self, ctx: &egui::Context) {
        if let Some(choice) = self.confirm_new {
            if !self.dirty {
                self.confirm_new = None;
                self.new_circuit(choice);
            } else {
                let mut keep = true;
                egui::Window::new("Discard changes?").collapsible(false).resizable(false).anchor(Align2::CENTER_CENTER, vec2(0.0, 0.0)).show(ctx, |ui| {
                    ui.label("The current circuit has unsaved changes.");
                    ui.horizontal(|ui| {
                        if ui.button("Discard and continue").clicked() {
                            self.new_circuit(choice);
                            keep = false;
                        }
                        if ui.button("Cancel").clicked() {
                            keep = false;
                        }
                    });
                });
                if !keep {
                    self.confirm_new = None;
                }
            }
        }
        if self.about_open {
            egui::Window::new("About Circuit Bench").collapsible(false).resizable(false).open(&mut self.about_open).show(ctx, |ui| {
                ui.heading("Circuit Bench");
                ui.label("A schematic capture and circuit simulation workbench.");
                ui.label("Draw circuits from a parts bin, wire them, and test them live with a multimeter, function generator and oscilloscope — or run DC, AC and transient analyses and read the results in the grapher.");
                ui.label(RichText::new("Engine: modified nodal analysis with Newton–Raphson for diodes and trapezoidal integration.").small().weak());
            });
        }
        if self.help_open {
            egui::Window::new("Quick guide").default_width(460.0).open(&mut self.help_open).show(ctx, |ui| {
                for (h, t) in [
                    ("Place parts", "Click a part in the Parts bin (left) or an instrument (right), then click the sheet. Press R to rotate before placing; hold Shift to place several."),
                    ("Wire", "Hover a pin until the red circle appears, click, then click where the wire should turn and click another pin or wire to finish. Double-click ends a wire anywhere. Esc cancels."),
                    ("Edit", "Drag parts to move them (wires follow). Double-click a part for its properties, or a wire to change its colour. Ctrl+R rotates, Del deletes, Ctrl+Z undoes."),
                    ("Ground", "Every circuit needs at least one Ground part connected to it."),
                    ("Simulate", "Press the green Run button (F5). Meters, probes, LEDs and lamps update live. Switches toggle with their key (Space by default) or a click; potentiometers turn with A / Shift+A."),
                    ("Instruments", "Double-click the multimeter, function generator or oscilloscope to open its panel. The oscilloscope shows channel A and B relative to its G pin (or ground when G is open)."),
                    ("Analyses", "Simulate ▸ Analyses runs DC operating point, AC sweep, transient and DC sweep. Results appear in the Grapher, where you can export CSV."),
                ] {
                    ui.label(RichText::new(h).strong());
                    ui.label(t);
                    ui.add_space(4.0);
                }
            });
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.frame += 1;
        self.handle_keys(ctx);
        if self.running && !self.paused {
            self.run_sim_frame();
        } else {
            self.last_frame = None;
        }

        egui::TopBottomPanel::top("menu").show(ctx, |ui| self.menu_bar(ui, ctx));
        egui::TopBottomPanel::top("toolbar").frame(egui::Frame::side_top_panel(&ctx.style()).inner_margin(egui::Margin::symmetric(8.0, 5.0))).show(ctx, |ui| self.toolbar(ui));
        egui::TopBottomPanel::bottom("status").show(ctx, |ui| self.status_bar(ui));
        if self.show_sheet {
            egui::TopBottomPanel::bottom("sheet").resizable(true).default_height(150.0).min_height(80.0).show(ctx, |ui| self.spreadsheet(ui));
        }
        if self.show_parts {
            egui::SidePanel::left("parts").resizable(true).default_width(215.0).show(ctx, |ui| self.parts_panel(ui));
        }
        egui::SidePanel::right("instruments").resizable(true).default_width(200.0).show(ctx, |ui| self.right_panel(ui));
        egui::CentralPanel::default().frame(egui::Frame::none().fill(Color32::WHITE)).show(ctx, |ui| self.canvas(ui));

        self.instrument_windows(ctx);
        self.props_window(ctx);
        self.wire_window(ctx);
        self.analysis_window(ctx);
        self.grapher_window(ctx);
        self.file_window(ctx);
        self.misc_windows(ctx);

        let title = format!(
            "Circuit Bench — {}{}",
            self.file_path.as_ref().and_then(|p| p.file_name()).map(|n| n.to_string_lossy().to_string()).unwrap_or_else(|| if self.circuit.title.is_empty() { "Untitled".into() } else { self.circuit.title.clone() }),
            if self.dirty { " *" } else { "" }
        );
        if self.frame % 30 == 1 {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title));
        }

        // screenshot mode
        if let Some(path) = self.screenshot.clone() {
            if self.frame >= 120 && !self.shot_requested {
                self.shot_requested = true;
                ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot);
            }
            let shot = ctx.input(|i| {
                i.events.iter().find_map(|e| if let egui::Event::Screenshot { image, .. } = e { Some(image.clone()) } else { None })
            });
            if let Some(img) = shot {
                if let Err(e) = save_png(&path, &img) {
                    eprintln!("screenshot failed: {}", e);
                }
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            }
            if self.frame > 600 {
                // never hang
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            }
            ctx.request_repaint();
        }
        if self.running && !self.paused {
            ctx.request_repaint();
        }
    }
}

// ---------------------------------------------------------------- helpers

const PART_GROUPS: &[(&str, &[Kind])] = &[
    ("Sources", &[Kind::DcVoltage, Kind::AcVoltage, Kind::DcCurrent, Kind::Ground]),
    ("Basic", &[Kind::Resistor, Kind::Capacitor, Kind::Inductor, Kind::Potentiometer, Kind::Switch]),
    ("Diodes", &[Kind::Diode, Kind::Zener, Kind::Led]),
    ("Indicators", &[Kind::Voltmeter, Kind::Ammeter, Kind::Probe, Kind::Lamp]),
];

fn part_row(ui: &mut Ui, kind: Kind, selected: bool) -> egui::Response {
    let w = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(vec2(w, 28.0), Sense::click());
    let p = ui.painter_at(rect);
    if selected {
        p.rect_filled(rect, 4.0, Color32::from_rgb(190, 215, 250));
    } else if resp.hovered() {
        p.rect_filled(rect, 4.0, Color32::from_rgb(215, 225, 240));
    }
    let icon = Rect::from_min_size(rect.min + vec2(4.0, 3.0), vec2(42.0, 22.0));
    draw::draw_icon(&p, icon, kind);
    p.text(pos2(icon.right() + 8.0, rect.center().y), Align2::LEFT_CENTER, kind.name(), FontId::proportional(13.5), Color32::from_gray(30));
    resp.on_hover_text(format!("Place a {}", kind.name().to_lowercase()))
}

#[derive(Clone, Copy)]
enum SimIcon {
    Run,
    Pause,
    Stop,
}

fn sim_button(ui: &mut Ui, icon: SimIcon, active: bool, tip: &str) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(vec2(34.0, 26.0), Sense::click());
    let p = ui.painter_at(rect);
    let base = match icon {
        SimIcon::Run => Color32::from_rgb(30, 160, 60),
        SimIcon::Pause => Color32::from_rgb(220, 160, 0),
        SimIcon::Stop => Color32::from_rgb(200, 40, 40),
    };
    let fill = if active { base } else if resp.hovered() { Color32::from_gray(215) } else { Color32::from_gray(228) };
    p.rect(rect.shrink(1.0), 4.0, fill, Stroke::new(1.0, Color32::from_gray(160)));
    let fg = if active { Color32::WHITE } else { base };
    let c = rect.center();
    match icon {
        SimIcon::Run => {
            p.add(Shape::convex_polygon(vec![c + vec2(-5.0, -7.0), c + vec2(7.0, 0.0), c + vec2(-5.0, 7.0)], fg, Stroke::NONE));
        }
        SimIcon::Pause => {
            p.rect_filled(Rect::from_center_size(c + vec2(-3.5, 0.0), vec2(4.0, 13.0)), 1.0, fg);
            p.rect_filled(Rect::from_center_size(c + vec2(3.5, 0.0), vec2(4.0, 13.0)), 1.0, fg);
        }
        SimIcon::Stop => {
            p.rect_filled(Rect::from_center_size(c, vec2(12.0, 12.0)), 1.0, fg);
        }
    }
    resp.on_hover_text(tip)
}

fn key_field(ui: &mut Ui, key: &mut char) {
    let mut s = if *key == ' ' { "Space".to_string() } else { key.to_string() };
    let r = ui.add(egui::TextEdit::singleline(&mut s).desired_width(60.0));
    if r.changed() {
        let t = s.trim();
        if t.eq_ignore_ascii_case("space") || t.is_empty() {
            *key = ' ';
        } else if let Some(c) = t.chars().last() {
            if c.is_ascii_alphanumeric() {
                *key = c.to_ascii_uppercase();
            }
        }
    }
}

fn natural_key(s: &str) -> (String, u32) {
    let p: String = s.chars().take_while(|c| !c.is_ascii_digit()).collect();
    let n: u32 = s[p.len()..].parse().unwrap_or(0);
    (p, n)
}

fn palette(k: usize) -> Color32 {
    const P: [Color32; 8] = [
        Color32::from_rgb(220, 40, 40),
        Color32::from_rgb(30, 90, 220),
        Color32::from_rgb(20, 150, 60),
        Color32::from_rgb(230, 130, 0),
        Color32::from_rgb(140, 50, 180),
        Color32::from_rgb(0, 150, 160),
        Color32::from_rgb(120, 80, 40),
        Color32::from_rgb(90, 90, 90),
    ];
    P[k % P.len()]
}

fn seg_dist(p: (f32, f32), a: GP, b: GP) -> f32 {
    let (ax, ay, bx, by) = (a.x as f32, a.y as f32, b.x as f32, b.y as f32);
    let (dx, dy) = (bx - ax, by - ay);
    let l2 = dx * dx + dy * dy;
    let t = if l2 > 0.0 { (((p.0 - ax) * dx + (p.1 - ay) * dy) / l2).clamp(0.0, 1.0) } else { 0.0 };
    let (cx, cy) = (ax + t * dx, ay + t * dy);
    ((p.0 - cx).powi(2) + (p.1 - cy).powi(2)).sqrt()
}

fn dashed_rect(p: &egui::Painter, r: Rect, col: Color32) {
    let pts = [r.left_top(), r.right_top(), r.right_bottom(), r.left_bottom(), r.left_top()];
    for w in pts.windows(2) {
        p.extend(Shape::dashed_line(&[w[0], w[1]], Stroke::new(1.2, col), 4.0, 3.0));
    }
}

/// Points where three or more conductors meet.
fn junctions(c: &Circuit) -> Vec<GP> {
    let mut pins: HashMap<GP, usize> = HashMap::new();
    for comp in &c.components {
        for p in comp.pin_positions() {
            *pins.entry(p).or_default() += 1;
        }
    }
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for w in &c.wires {
        for e in [w.points[0], *w.points.last().unwrap()] {
            if !seen.insert(e) {
                continue;
            }
            let mut deg = pins.get(&e).copied().unwrap_or(0);
            for w2 in &c.wires {
                let n = w2.points.len();
                if w2.points[0] == e {
                    deg += 1;
                }
                if n > 1 && w2.points[n - 1] == e {
                    deg += 1;
                }
                for k in 1..n.saturating_sub(1) {
                    if w2.points[k] == e {
                        deg += 2;
                    }
                }
                for k in 1..n {
                    let (a, b) = (w2.points[k - 1], w2.points[k]);
                    if a != e && b != e && sim::on_segment(e, a, b) {
                        deg += 2;
                    }
                }
            }
            if deg >= 3 {
                out.push(e);
            }
        }
    }
    out
}

/// Keep wires attached to moved or rotated parts.
fn reroute(orig: &Circuit, c: &mut Circuit, changed: &HashSet<u64>, translate: Option<GP>, moved_wires: &HashSet<u64>) {
    let mut map: HashMap<GP, GP> = HashMap::new();
    for oc in &orig.components {
        if !changed.contains(&oc.id) {
            continue;
        }
        if let Some(nc) = c.comp(oc.id) {
            for (a, b) in oc.pin_positions().into_iter().zip(nc.pin_positions()) {
                map.insert(a, b);
            }
        }
    }
    for w in c.wires.iter_mut() {
        if moved_wires.contains(&w.id) {
            if let Some(d) = translate {
                for p in w.points.iter_mut() {
                    *p = p.add(d);
                }
            }
            continue;
        }
        let n = w.points.len();
        if n < 2 {
            continue;
        }
        let f = map.get(&w.points[0]).copied();
        let l = map.get(&w.points[n - 1]).copied();
        match (f, l, translate) {
            (Some(_), Some(_), Some(d)) => {
                for p in w.points.iter_mut() {
                    *p = p.add(d);
                }
            }
            _ => {
                if let Some(nf) = f {
                    reroute_end(&mut w.points, nf);
                }
                if let Some(nl) = l {
                    w.points.reverse();
                    reroute_end(&mut w.points, nl);
                    w.points.reverse();
                }
            }
        }
        w.points = simplify(std::mem::take(&mut w.points));
    }
    c.wires.retain(|w| w.points.len() >= 2);
}

fn reroute_end(pts: &mut Vec<GP>, new: GP) {
    let p0 = pts[0];
    let p1 = pts[1];
    if p0 == new {
        return;
    }
    let horizontal = p0.y == p1.y;
    pts[0] = new;
    if new.x == p1.x || new.y == p1.y {
        return;
    }
    if pts.len() == 2 {
        if horizontal {
            let mx = (new.x + p1.x) / 2;
            pts.splice(1..1, [GP::new(mx, new.y), GP::new(mx, p1.y)]);
        } else {
            let my = (new.y + p1.y) / 2;
            pts.splice(1..1, [GP::new(new.x, my), GP::new(p1.x, my)]);
        }
    } else {
        let elbow = if horizontal { GP::new(p1.x, new.y) } else { GP::new(new.x, p1.y) };
        pts.insert(1, elbow);
    }
}

/// Measure every metering part after a time step.
fn sample(c: &Circuit, sim: &Sim, meters: &mut HashMap<u64, Meter>, scopes: &mut HashMap<u64, Scope>, window: f64) {
    let t = sim.t;
    for (ci, comp) in c.components.iter().enumerate() {
        let nets = &sim.nl.comp_nets[ci];
        let val = match comp.kind {
            Kind::Voltmeter => Some(sim.v(nets[0]) - sim.v(nets[1])),
            Kind::Ammeter => Some(sim.comp_current(ci)),
            Kind::Probe => Some(sim.v(nets[0])),
            Kind::Led => Some(sim.comp_current(ci)),
            Kind::Lamp => Some((sim.v(nets[0]) - sim.v(nets[1])) * sim.comp_current(ci)),
            Kind::Multimeter => Some(match comp.params.meter {
                MeterMode::Amps => sim.comp_current(ci),
                MeterMode::Ohms => (sim.v(nets[0]) - sim.v(nets[1])) / sim::OHM_TEST_I,
                _ => sim.v(nets[0]) - sim.v(nets[1]),
            }),
            Kind::Oscilloscope => {
                let g = if sim.nl.net_pin_count[nets[3]] > 1 { sim.v(nets[3]) } else { 0.0 };
                let sc = scopes.entry(comp.id).or_default();
                sc.push(t, sim.v(nets[0]) - g, sim.v(nets[1]) - g, sim.v(nets[2]) - g);
                None
            }
            _ => None,
        };
        if let Some(v) = val {
            let m = meters.entry(comp.id).or_default();
            m.window = window;
            m.push(t, v);
        }
    }
}

fn multimeter_text(c: &Component, m: &Meter) -> String {
    let p = &c.params;
    match p.meter {
        MeterMode::Volts => fmt_reading(if p.ac { m.ac_rms() } else { m.mean() }, "V"),
        MeterMode::Amps => fmt_reading(if p.ac { m.ac_rms() } else { m.mean() }, "A"),
        MeterMode::Ohms => {
            let r = m.mean();
            if !(0.0..=2e8).contains(&r) {
                "OL Ω".into()
            } else {
                fmt_reading(r, "Ω")
            }
        }
        MeterMode::Decibel => {
            let v = if p.ac { m.ac_rms() } else { m.mean().abs() };
            format!("{:.3} dB", 20.0 * (v.max(1e-12) / 0.7746).log10())
        }
    }
}

fn scope_colors(c: &Circuit, idx: usize) -> [Color32; 2] {
    let pins = c.components[idx].pin_positions();
    let mut out = [Color32::from_rgb(255, 80, 60), Color32::from_rgb(70, 160, 255)];
    for k in 0..2 {
        if let Some(w) = c.wires.iter().find(|w| w.points[0] == pins[k] || *w.points.last().unwrap() == pins[k]) {
            if w.color != WireColor::Red || k == 0 {
                let [r, g, b] = w.color.rgb();
                let col = Color32::from_rgb(r, g, b);
                // brighten dark colours for the black screen
                out[k] = if w.color == WireColor::Black { Color32::from_gray(230) } else { brighten(col) };
            }
        }
    }
    out
}

fn brighten(c: Color32) -> Color32 {
    let f = |v: u8| ((v as f32 * 0.6) + 100.0).min(255.0) as u8;
    Color32::from_rgb(f(c.r()), f(c.g()), f(c.b()))
}

fn erc(c: &Circuit) -> Vec<String> {
    let mut out = Vec::new();
    let nl = sim::build_netlist(c);
    if !nl.has_ground && !c.components.is_empty() {
        out.push("No ground: place a Ground part and connect it.".into());
    }
    for (ci, comp) in c.components.iter().enumerate() {
        let optional = |k: usize| match comp.kind {
            Kind::Oscilloscope => k >= 1,
            Kind::FuncGen => k == 2,
            Kind::Potentiometer => k == 2,
            _ => false,
        };
        for (k, n) in nl.comp_nets[ci].iter().enumerate() {
            if nl.net_pin_count[*n] == 1 && *n != 0 && !optional(k) {
                out.push(format!("{} pin {} is not connected.", comp.refdes, comp.kind.pins()[k].2));
            }
        }
        let nets = &nl.comp_nets[ci];
        if nets.len() == 2 && nets[0] == nets[1] && !matches!(comp.kind, Kind::Ground | Kind::Probe) {
            out.push(format!("{} is shorted (both pins on the same net).", comp.refdes));
        }
    }
    for (wi, n) in nl.wire_nets.iter().enumerate() {
        if *n == usize::MAX {
            out.push(format!("Wire #{} is not connected to any part.", wi + 1));
        }
    }
    let mut seen: HashMap<&str, usize> = HashMap::new();
    for comp in &c.components {
        if !comp.refdes.is_empty() {
            *seen.entry(&comp.refdes).or_default() += 1;
        }
    }
    for (k, v) in seen {
        if v > 1 {
            out.push(format!("RefDes {} is used {} times.", k, v));
        }
    }
    out
}

fn spice_netlist(c: &Circuit) -> String {
    let nl = sim::build_netlist(c);
    let mut s = format!("* {}\n* exported by Circuit Bench\n", if c.title.is_empty() { "Untitled" } else { &c.title });
    let mut need_d = false;
    let mut models = Vec::new();
    for (ci, comp) in c.components.iter().enumerate() {
        let n = &nl.comp_nets[ci];
        let p = &comp.params;
        let name = comp.refdes.replace(' ', "_");
        match comp.kind {
            Kind::Resistor => s += &format!("R{} {} {} {}\n", name.trim_start_matches('R'), n[0], n[1], p.value),
            Kind::Capacitor => s += &format!("C{} {} {} {} IC={}\n", name.trim_start_matches('C'), n[0], n[1], p.value, p.ic),
            Kind::Inductor => s += &format!("L{} {} {} {}\n", name.trim_start_matches('L'), n[0], n[1], p.value),
            Kind::Potentiometer => {
                let r = p.value * p.setting / 100.0;
                s += &format!("R{}a {} {} {}\nR{}b {} {} {}\n", name, n[0], n[2], r.max(1e-3), name, n[2], n[1], (p.value - r).max(1e-3));
            }
            Kind::DcVoltage => s += &format!("V{} {} {} DC {}\n", name.trim_start_matches('V'), n[0], n[1], p.value),
            Kind::DcCurrent => s += &format!("I{} {} {} DC {}\n", name.trim_start_matches('I'), n[1], n[0], p.value),
            Kind::AcVoltage => s += &format!("V{} {} {} SIN({} {} {} 0 0 {}) AC {}\n", name.trim_start_matches('V'), n[0], n[1], p.offset, p.value, p.freq, p.phase, p.value),
            Kind::Diode => {
                need_d = true;
                s += &format!("D{} {} {} DGEN\n", name.trim_start_matches('D'), n[0], n[1]);
            }
            Kind::Zener => {
                models.push(format!(".model DZ{} D(IS={} N={} BV={} IBV=1m)", name, p.is, p.n, p.value));
                s += &format!("D{} {} {} DZ{}\n", name.trim_start_matches('D'), n[0], n[1], name);
            }
            Kind::Led => {
                models.push(format!(".model DLED{} D(IS={:e} N=2)", name, 0.01 / (p.led.forward_voltage() / (2.0 * 0.025852)).exp()));
                s += &format!("D{} {} {} DLED{}\n", name, n[0], n[1], name);
            }
            Kind::Switch => s += &format!("R{}sw {} {} {}\n", name, n[0], n[1], if p.closed { 1e-3 } else { 1e10 }),
            Kind::Lamp => s += &format!("R{}lamp {} {} {}\n", name, n[0], n[1], p.value * p.value / p.power.max(1e-9)),
            Kind::Ammeter => s += &format!("V{}amm {} {} DC 0\n", name, n[0], n[1]),
            Kind::Voltmeter => s += &format!("R{}vm {} {} 10Meg\n", name, n[0], n[1]),
            Kind::FuncGen => {
                let wave = match p.wave {
                    Wave::Sine => format!("SIN({} {} {})", p.offset, p.value, p.freq),
                    _ => {
                        let per = 1.0 / p.freq.max(1e-12);
                        let on = per * p.duty / 100.0;
                        format!("PULSE({} {} 0 {} {} {} {})", p.offset - p.value, p.offset + p.value, per / 1000.0, per / 1000.0, on, per)
                    }
                };
                s += &format!("V{}p {} {} {} AC {}\n", name, n[0], n[1], wave, p.value);
            }
            Kind::Multimeter | Kind::Oscilloscope => s += &format!("* {} ({}) is a measuring instrument\n", comp.refdes, comp.kind.name()),
            Kind::Ground | Kind::Probe => {}
        }
    }
    if need_d {
        s += ".model DGEN D(IS=2.52n N=1.752)\n";
    }
    for m in models {
        s += &m;
        s += "\n";
    }
    s += ".tran 10u 10m\n.end\n";
    s
}

fn graph_csv(g: &GraphTab) -> String {
    match g {
        GraphTab::Op { rows, .. } => {
            let mut s = String::from("variable,value\n");
            for (n, v, _) in rows {
                s += &format!("{},{}\n", n, v);
            }
            s
        }
        GraphTab::Xy { xlabel, series, .. } => {
            let mut s = format!("{}", xlabel);
            for se in series {
                s += &format!(",{}", se.name);
            }
            s += "\n";
            let n = series.first().map(|x| x.pts.len()).unwrap_or(0);
            for i in 0..n {
                s += &format!("{}", series[0].pts[i][0]);
                for se in series {
                    s += &format!(",{}", se.pts.get(i).map(|p| p[1]).unwrap_or(f64::NAN));
                }
                s += "\n";
            }
            s
        }
        GraphTab::Ac { series, .. } => {
            let mut s = String::from("frequency");
            for se in series {
                s += &format!(",{} dB,{} phase", se.name, se.name);
            }
            s += "\n";
            let n = series.first().map(|x| x.mag.len()).unwrap_or(0);
            for i in 0..n {
                s += &format!("{}", 10f64.powf(series[0].mag[i][0]));
                for se in series {
                    s += &format!(",{},{}", se.mag[i][1], se.phase[i][1]);
                }
                s += "\n";
            }
            s
        }
    }
}

fn save_png(path: &Path, img: &egui::ColorImage) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        if !dir.as_os_str().is_empty() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
    }
    let file = std::fs::File::create(path).map_err(|e| e.to_string())?;
    let w = std::io::BufWriter::new(file);
    let mut enc = png::Encoder::new(w, img.size[0] as u32, img.size[1] as u32);
    enc.set_color(png::ColorType::Rgba);
    enc.set_depth(png::BitDepth::Eight);
    let mut writer = enc.write_header().map_err(|e| e.to_string())?;
    let mut data = Vec::with_capacity(img.pixels.len() * 4);
    for p in &img.pixels {
        let [r, g, b, _] = p.to_srgba_unmultiplied();
        data.extend_from_slice(&[r, g, b, 255]);
    }
    writer.write_image_data(&data).map_err(|e| e.to_string())?;
    Ok(())
}

