pub(super) fn log_freq_fmt(m: egui_plot::GridMark, _: usize, _: &std::ops::RangeInclusive<f64>) -> String {
    if (m.value - m.value.round()).abs() < 1e-6 {
        fmt_si(10f64.powf(m.value), "Hz")
    } else {
        String::new()
    }
}

pub(super) fn part_row(ui: &mut Ui, kind: Kind, selected: bool) -> egui::Response {
    let w = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(vec2(w, 28.0), Sense::click());
    let p = ui.painter_at(rect);
    if selected {
        p.rect_filled(rect, 4.0, Color32::from_rgb(190, 215, 250));
    } else if resp.hovered() {
        p.rect_filled(rect, 4.0, Color32::from_rgb(215, 225, 240));
    }
    let icon = Rect::from_min_size(rect.min + vec2(4.0, 3.0), vec2(42.0, 22.0));
    draw::draw_icon(&p, icon, kind);
    p.text(pos2(icon.right() + 8.0, rect.center().y), Align2::LEFT_CENTER, kind.name(), FontId::proportional(13.5), Color32::from_gray(30));
    resp.on_hover_text(format!("Place a {}", kind.name().to_lowercase()))
}

#[derive(Clone, Copy)]
pub(super) enum SimIcon {
    Run,
    Pause,
    Stop,
}

pub(super) fn sim_button(ui: &mut Ui, icon: SimIcon, active: bool, tip: &str) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(vec2(34.0, 26.0), Sense::click());
    let p = ui.painter_at(rect);
    let base = match icon {
        SimIcon::Run => Color32::from_rgb(30, 160, 60),
        SimIcon::Pause => Color32::from_rgb(220, 160, 0),
        SimIcon::Stop => Color32::from_rgb(200, 40, 40),
    };
    let fill = if active {
        base
    } else if resp.hovered() {
        Color32::from_gray(215)
    } else {
        Color32::from_gray(228)
    };
    p.rect(rect.shrink(1.0), 4.0, fill, Stroke::new(1.0, Color32::from_gray(160)));
    let fg = if active { Color32::WHITE } else { base };
    let c = rect.center();
    match icon {
        SimIcon::Run => {
            p.add(Shape::convex_polygon(vec![c + vec2(-5.0, -7.0), c + vec2(7.0, 0.0), c + vec2(-5.0, 7.0)], fg, Stroke::NONE));
        }
        SimIcon::Pause => {
            p.rect_filled(Rect::from_center_size(c + vec2(-3.5, 0.0), vec2(4.0, 13.0)), 1.0, fg);
            p.rect_filled(Rect::from_center_size(c + vec2(3.5, 0.0), vec2(4.0, 13.0)), 1.0, fg);
        }
        SimIcon::Stop => {
            p.rect_filled(Rect::from_center_size(c, vec2(12.0, 12.0)), 1.0, fg);
        }
    }
    resp.on_hover_text(tip)
}

pub(super) fn key_field(ui: &mut Ui, key: &mut char) {
    let mut s = if *key == ' ' { "Space".to_string() } else { key.to_string() };
    let r = ui.add(egui::TextEdit::singleline(&mut s).desired_width(60.0));
    if r.changed() {
        let t = s.trim();
        if t.eq_ignore_ascii_case("space") || t.is_empty() {
            *key = ' ';
        } else if let Some(c) = t.chars().last() {
            if c.is_ascii_alphanumeric() {
                *key = c.to_ascii_uppercase();
            }
        }
    }
}

pub(super) fn natural_key(s: &str) -> (String, u32) {
    let p: String = s.chars().take_while(|c| !c.is_ascii_digit()).collect();
    let n: u32 = s[p.len()..].parse().unwrap_or(0);
    (p, n)
}

pub(super) fn palette(k: usize) -> Color32 {
    const P: [Color32; 8] = [
        Color32::from_rgb(220, 40, 40),
        Color32::from_rgb(30, 90, 220),
        Color32::from_rgb(20, 150, 60),
        Color32::from_rgb(230, 130, 0),
        Color32::from_rgb(140, 50, 180),
        Color32::from_rgb(0, 150, 160),
        Color32::from_rgb(120, 80, 40),
        Color32::from_rgb(90, 90, 90),
    ];
    P[k % P.len()]
}

pub(super) fn seg_dist(p: (f32, f32), a: GP, b: GP) -> f32 {
    let (ax, ay, bx, by) = (a.x as f32, a.y as f32, b.x as f32, b.y as f32);
    let (dx, dy) = (bx - ax, by - ay);
    let l2 = dx * dx + dy * dy;
    let t = if l2 > 0.0 { (((p.0 - ax) * dx + (p.1 - ay) * dy) / l2).clamp(0.0, 1.0) } else { 0.0 };
    let (cx, cy) = (ax + t * dx, ay + t * dy);
    ((p.0 - cx).powi(2) + (p.1 - cy).powi(2)).sqrt()
}

pub(super) fn dashed_rect(p: &egui::Painter, r: Rect, col: Color32) {
    let pts = [r.left_top(), r.right_top(), r.right_bottom(), r.left_bottom(), r.left_top()];
    for w in pts.windows(2) {
        p.extend(Shape::dashed_line(&[w[0], w[1]], Stroke::new(1.2, col), 4.0, 3.0));
    }
}

/// Points where three or more conductors meet.
pub(super) fn junctions(c: &Circuit) -> Vec<GP> {
    let mut pins: HashMap<GP, usize> = HashMap::new();
    for comp in &c.components {
        for p in comp.pin_positions() {
            *pins.entry(p).or_default() += 1;
        }
    }
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for w in &c.wires {
        for e in [w.points[0], *w.points.last().unwrap()] {
            if !seen.insert(e) {
                continue;
            }
            let mut deg = pins.get(&e).copied().unwrap_or(0);
            for w2 in &c.wires {
                let n = w2.points.len();
                if w2.points[0] == e {
                    deg += 1;
                }
                if n > 1 && w2.points[n - 1] == e {
                    deg += 1;
                }
                for k in 1..n.saturating_sub(1) {
                    if w2.points[k] == e {
                        deg += 2;
                    }
                }
                for k in 1..n {
                    let (a, b) = (w2.points[k - 1], w2.points[k]);
                    if a != e && b != e && sim::on_segment(e, a, b) {
                        deg += 2;
                    }
                }
            }
            if deg >= 3 {
                out.push(e);
            }
        }
    }
    out
}

/// Keep wires attached to moved or rotated parts.
pub(super) fn reroute(orig: &Circuit, c: &mut Circuit, changed: &HashSet<u64>, translate: Option<GP>, moved_wires: &HashSet<u64>) {
    let mut map: HashMap<GP, GP> = HashMap::new();
    for oc in &orig.components {
        if !changed.contains(&oc.id) {
            continue;
        }
        if let Some(nc) = c.comp(oc.id) {
            for (a, b) in oc.pin_positions().into_iter().zip(nc.pin_positions()) {
                map.insert(a, b);
            }
        }
    }
    for w in c.wires.iter_mut() {
        if moved_wires.contains(&w.id) {
            if let Some(d) = translate {
                for p in w.points.iter_mut() {
                    *p = p.add(d);
                }
            }
            continue;
        }
        let n = w.points.len();
        if n < 2 {
            continue;
        }
        let f = map.get(&w.points[0]).copied();
        let l = map.get(&w.points[n - 1]).copied();
        match (f, l, translate) {
            (Some(_), Some(_), Some(d)) => {
                for p in w.points.iter_mut() {
                    *p = p.add(d);
                }
            }
            _ => {
                if let Some(nf) = f {
                    reroute_end(&mut w.points, nf);
                }
                if let Some(nl) = l {
                    w.points.reverse();
                    reroute_end(&mut w.points, nl);
                    w.points.reverse();
                }
            }
        }
        w.points = simplify(std::mem::take(&mut w.points));
    }
    c.wires.retain(|w| w.points.len() >= 2);
}

fn reroute_end(pts: &mut Vec<GP>, new: GP) {
    let p0 = pts[0];
    let p1 = pts[1];
    if p0 == new {
        return;
    }
    let horizontal = p0.y == p1.y;
    pts[0] = new;
    if new.x == p1.x || new.y == p1.y {
        return;
    }
    if pts.len() == 2 {
        if horizontal {
            let mx = (new.x + p1.x) / 2;
            pts.splice(1..1, [GP::new(mx, new.y), GP::new(mx, p1.y)]);
        } else {
            let my = (new.y + p1.y) / 2;
            pts.splice(1..1, [GP::new(new.x, my), GP::new(p1.x, my)]);
        }
    } else {
        let elbow = if horizontal { GP::new(p1.x, new.y) } else { GP::new(new.x, p1.y) };
        pts.insert(1, elbow);
    }
}

/// Measure every metering part after a time step.
pub(super) fn sample(c: &Circuit, sim: &Sim, meters: &mut HashMap<u64, Meter>, scopes: &mut HashMap<u64, Scope>, window: f64) {
    let t = sim.t;
    for (ci, comp) in c.components.iter().enumerate() {
        let nets = &sim.nl.comp_nets[ci];
        let val = match comp.kind {
            Kind::Voltmeter => Some(sim.v(nets[0]) - sim.v(nets[1])),
            Kind::Ammeter => Some(sim.comp_current(ci)),
            Kind::Probe => Some(sim.v(nets[0])),
            Kind::Led => Some(sim.comp_current(ci)),
            Kind::Lamp => Some((sim.v(nets[0]) - sim.v(nets[1])) * sim.comp_current(ci)),
            Kind::Multimeter => Some(match comp.params.meter {
                MeterMode::Amps => sim.comp_current(ci),
                MeterMode::Ohms => (sim.v(nets[0]) - sim.v(nets[1])) / sim::OHM_TEST_I,
                _ => sim.v(nets[0]) - sim.v(nets[1]),
            }),
            Kind::Oscilloscope => {
                let g = if sim.nl.net_pin_count[nets[3]] > 1 { sim.v(nets[3]) } else { 0.0 };
                let sc = scopes.entry(comp.id).or_default();
                sc.push(t, sim.v(nets[0]) - g, sim.v(nets[1]) - g, sim.v(nets[2]) - g);
                None
            }
            _ => None,
        };
        if let Some(v) = val {
            let m = meters.entry(comp.id).or_default();
            m.window = window;
            m.push(t, v);
        }
    }
}

pub(super) fn multimeter_text(c: &Component, m: &Meter) -> String {
    let p = &c.params;
    match p.meter {
        MeterMode::Volts => fmt_reading(if p.ac { m.ac_rms() } else { m.mean() }, "V"),
        MeterMode::Amps => fmt_reading(if p.ac { m.ac_rms() } else { m.mean() }, "A"),
        MeterMode::Ohms => {
            let r = m.mean();
            if !(0.0..=2e8).contains(&r) {
                "OL Ω".into()
            } else {
                fmt_reading(r, "Ω")
            }
        }
        MeterMode::Decibel => {
            let v = if p.ac { m.ac_rms() } else { m.mean().abs() };
            format!("{:.3} dB", 20.0 * (v.max(1e-12) / 0.7746).log10())
        }
    }
}

pub(super) fn scope_colors(c: &Circuit, idx: usize) -> [Color32; 2] {
    let pins = c.components[idx].pin_positions();
    let mut out = [Color32::from_rgb(255, 80, 60), Color32::from_rgb(70, 160, 255)];
    for k in 0..2 {
        if let Some(w) = c.wires.iter().find(|w| w.points[0] == pins[k] || *w.points.last().unwrap() == pins[k]) {
            if w.color != WireColor::Red || k == 0 {
                let [r, g, b] = w.color.rgb();
                out[k] = if w.color == WireColor::Black { Color32::from_gray(230) } else { brighten(Color32::from_rgb(r, g, b)) };
            }
        }
    }
    out
}

fn brighten(c: Color32) -> Color32 {
    let f = |v: u8| ((v as f32 * 0.6) + 100.0).min(255.0) as u8;
    Color32::from_rgb(f(c.r()), f(c.g()), f(c.b()))
}

pub(super) fn erc(c: &Circuit) -> Vec<String> {
    let mut out = Vec::new();
    let nl = sim::build_netlist(c);
    if !nl.has_ground && !c.components.is_empty() {
        out.push("No ground: place a Ground part and connect it.".into());
    }
    for (ci, comp) in c.components.iter().enumerate() {
        let optional = |k: usize| match comp.kind {
            Kind::Oscilloscope => k >= 1,
            Kind::FuncGen => k == 2,
            Kind::Potentiometer => k == 2,
            _ => false,
        };
        for (k, n) in nl.comp_nets[ci].iter().enumerate() {
            if nl.net_pin_count[*n] == 1 && *n != 0 && !optional(k) {
                out.push(format!("{} pin {} is not connected.", comp.refdes, comp.kind.pins()[k].2));
            }
        }
        let nets = &nl.comp_nets[ci];
        if nets.len() == 2 && nets[0] == nets[1] && !matches!(comp.kind, Kind::Ground | Kind::Probe) {
            out.push(format!("{} is shorted (both pins on the same net).", comp.refdes));
        }
    }
    for (wi, n) in nl.wire_nets.iter().enumerate() {
        if *n == usize::MAX {
            out.push(format!("Wire #{} is not connected to any part.", wi + 1));
        }
    }
    let mut seen: HashMap<&str, usize> = HashMap::new();
    for comp in &c.components {
        if !comp.refdes.is_empty() {
            *seen.entry(&comp.refdes).or_default() += 1;
        }
    }
    for (k, v) in seen {
        if v > 1 {
            out.push(format!("RefDes {} is used {} times.", k, v));
        }
    }
    out
}

pub(super) fn spice_netlist(c: &Circuit) -> String {
    let nl = sim::build_netlist(c);
    let mut s = format!("* {}\n* exported by Circuit Bench\n", if c.title.is_empty() { "Untitled" } else { &c.title });
    let mut need_d = false;
    let mut models = Vec::new();
    for (ci, comp) in c.components.iter().enumerate() {
        let n = &nl.comp_nets[ci];
        let p = &comp.params;
        let name = comp.refdes.replace(' ', "_");
        match comp.kind {
            Kind::Resistor => s += &format!("R{} {} {} {}\n", name.trim_start_matches('R'), n[0], n[1], p.value),
            Kind::Capacitor => s += &format!("C{} {} {} {} IC={}\n", name.trim_start_matches('C'), n[0], n[1], p.value, p.ic),
            Kind::Inductor => s += &format!("L{} {} {} {}\n", name.trim_start_matches('L'), n[0], n[1], p.value),
            Kind::Potentiometer => {
                let r = p.value * p.setting / 100.0;
                s += &format!("R{}a {} {} {}\nR{}b {} {} {}\n", name, n[0], n[2], r.max(1e-3), name, n[2], n[1], (p.value - r).max(1e-3));
            }
            Kind::DcVoltage => s += &format!("V{} {} {} DC {}\n", name.trim_start_matches('V'), n[0], n[1], p.value),
            Kind::DcCurrent => s += &format!("I{} {} {} DC {}\n", name.trim_start_matches('I'), n[1], n[0], p.value),
            Kind::AcVoltage => s += &format!("V{} {} {} SIN({} {} {} 0 0 {}) AC {}\n", name.trim_start_matches('V'), n[0], n[1], p.offset, p.value, p.freq, p.phase, p.value),
            Kind::Diode => {
                need_d = true;
                s += &format!("D{} {} {} DGEN\n", name.trim_start_matches('D'), n[0], n[1]);
            }
            Kind::Zener => {
                models.push(format!(".model DZ{} D(IS={} N={} BV={} IBV=1m)", name, p.is, p.n, p.value));
                s += &format!("D{} {} {} DZ{}\n", name.trim_start_matches('D'), n[0], n[1], name);
            }
            Kind::Led => {
                models.push(format!(".model DLED{} D(IS={:e} N=2)", name, 0.01 / (p.led.forward_voltage() / (2.0 * 0.025852)).exp()));
                s += &format!("D{} {} {} DLED{}\n", name, n[0], n[1], name);
            }
            Kind::Switch => s += &format!("R{}sw {} {} {}\n", name, n[0], n[1], if p.closed { 1e-3 } else { 1e10 }),
            Kind::Lamp => s += &format!("R{}lamp {} {} {}\n", name, n[0], n[1], p.value * p.value / p.power.max(1e-9)),
            Kind::Ammeter => s += &format!("V{}amm {} {} DC 0\n", name, n[0], n[1]),
            Kind::Voltmeter => s += &format!("R{}vm {} {} 10Meg\n", name, n[0], n[1]),
            Kind::FuncGen => {
                let wave = match p.wave {
                    Wave::Sine => format!("SIN({} {} {})", p.offset, p.value, p.freq),
                    _ => {
                        let per = 1.0 / p.freq.max(1e-12);
                        let on = per * p.duty / 100.0;
                        format!("PULSE({} {} 0 {} {} {} {})", p.offset - p.value, p.offset + p.value, per / 1000.0, per / 1000.0, on, per)
                    }
                };
                s += &format!("V{}p {} {} {} AC {}\n", name, n[0], n[1], wave, p.value);
            }
            Kind::Multimeter | Kind::Oscilloscope => s += &format!("* {} ({}) is a measuring instrument\n", comp.refdes, comp.kind.name()),
            Kind::Ground | Kind::Probe => {}
        }
    }
    if need_d {
        s += ".model DGEN D(IS=2.52n N=1.752)\n";
    }
    for m in models {
        s += &m;
        s += "\n";
    }
    s += ".tran 10u 10m\n.end\n";
    s
}

pub(super) fn graph_csv(g: &GraphTab) -> String {
    match g {
        GraphTab::Op { rows, .. } => {
            let mut s = String::from("variable,value\n");
            for (n, v, _) in rows {
                s += &format!("{},{}\n", n, v);
            }
            s
        }
        GraphTab::Xy { xlabel, series, .. } => {
            let mut s = xlabel.to_string();
            for se in series {
                s += &format!(",{}", se.name);
            }
            s += "\n";
            let n = series.first().map(|x| x.pts.len()).unwrap_or(0);
            for i in 0..n {
                s += &format!("{}", series[0].pts[i][0]);
                for se in series {
                    s += &format!(",{}", se.pts.get(i).map(|p| p[1]).unwrap_or(f64::NAN));
                }
                s += "\n";
            }
            s
        }
        GraphTab::Ac { series, .. } => {
            let mut s = String::from("frequency");
            for se in series {
                s += &format!(",{} dB,{} phase", se.name, se.name);
            }
            s += "\n";
            let n = series.first().map(|x| x.mag.len()).unwrap_or(0);
            for i in 0..n {
                s += &format!("{}", 10f64.powf(series[0].mag[i][0]));
                for se in series {
                    s += &format!(",{},{}", se.mag[i][1], se.phase[i][1]);
                }
                s += "\n";
            }
            s
        }
    }
}

pub(super) fn save_png(path: &Path, img: &egui::ColorImage) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        if !dir.as_os_str().is_empty() {
            std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        }
    }
    let file = std::fs::File::create(path).map_err(|e| e.to_string())?;
    let w = std::io::BufWriter::new(file);
    let mut enc = png::Encoder::new(w, img.size[0] as u32, img.size[1] as u32);
    enc.set_color(png::ColorType::Rgba);
    enc.set_depth(png::BitDepth::Eight);
    let mut writer = enc.write_header().map_err(|e| e.to_string())?;
    let mut data = Vec::with_capacity(img.pixels.len() * 4);
    for p in &img.pixels {
        let [r, g, b, _] = p.to_srgba_unmultiplied();
        data.extend_from_slice(&[r, g, b, 255]);
    }
    writer.write_image_data(&data).map_err(|e| e.to_string())?;
    Ok(())
}

//! The schematic sheet: drawing, hit testing, placing, wiring and moving parts.

use super::util::*;
use super::*;

impl App {
    pub(super) fn fit_view(&mut self, rect: Rect) {
        let mut lo = (f32::MAX, f32::MAX);
        let mut hi = (f32::MIN, f32::MIN);
        let mut any = false;
        for c in &self.circuit.components {
            let (x0, y0, x1, y1) = c.kind.bounds();
            for (x, y) in [(x0, y0 - 2.5), (x1, y1 + 2.5), (x0, y1 + 2.5), (x1, y0 - 2.5)] {
                let (rx, ry) = rotate_f(x, y, c.rot);
                let (wx, wy) = (c.pos.x as f32 + rx, c.pos.y as f32 + ry);
                lo = (lo.0.min(wx), lo.1.min(wy));
                hi = (hi.0.max(wx), hi.1.max(wy));
                any = true;
            }
        }
        for w in &self.circuit.wires {
            for p in &w.points {
                lo = (lo.0.min(p.x as f32), lo.1.min(p.y as f32));
                hi = (hi.0.max(p.x as f32), hi.1.max(p.y as f32));
                any = true;
            }
        }
        if !any {
            self.zoom = 1.6;
            self.pan = rect.size() / 2.0;
            return;
        }
        let w = (hi.0 - lo.0 + 8.0) * GRID;
        let h = (hi.1 - lo.1 + 8.0) * GRID;
        self.zoom = (rect.width() / w).min(rect.height() / h).clamp(0.4, 3.0);
        let s = GRID * self.zoom;
        let cx = (lo.0 + hi.0) / 2.0;
        let cy = (lo.1 + hi.1) / 2.0;
        self.pan = rect.size() / 2.0 - vec2(cx * s, cy * s);
    }

    pub(super) fn comp_screen_rect(c: &Component, origin: Pos2, s: f32) -> Rect {
        let (x0, y0, x1, y1) = c.kind.bounds();
        let mut r = Rect::NOTHING;
        for (x, y) in [(x0, y0), (x1, y0), (x1, y1), (x0, y1)] {
            let (rx, ry) = rotate_f(x, y, c.rot);
            r.extend_with(origin + vec2((c.pos.x as f32 + rx) * s, (c.pos.y as f32 + ry) * s));
        }
        r
    }

    pub(super) fn canvas(&mut self, ui: &mut Ui) {
        let (resp, painter) = ui.allocate_painter(ui.available_size(), Sense::click_and_drag());
        let rect = resp.rect;
        if self.need_fit {
            self.fit_view(rect);
            self.need_fit = false;
        }
        // zoom / pan with wheel and trackpad (Ctrl/Cmd + wheel or pinch zooms)
        if resp.hovered() {
            let (scroll, zd, hover) = ui.input(|i| (i.smooth_scroll_delta, i.zoom_delta(), i.pointer.hover_pos()));
            if zd != 1.0 {
                if let Some(m) = hover {
                    let old_s = GRID * self.zoom;
                    let world = (m - rect.min - self.pan) / old_s;
                    self.zoom = (self.zoom * zd).clamp(0.25, 8.0);
                    let new_s = GRID * self.zoom;
                    self.pan = m - rect.min - world * new_s;
                }
            } else if scroll != egui::Vec2::ZERO {
                self.pan += scroll;
            }
        }
        if resp.dragged_by(egui::PointerButton::Middle) || resp.dragged_by(egui::PointerButton::Secondary) {
            self.pan += resp.drag_delta();
        }
        let s = GRID * self.zoom;
        let origin = rect.min + self.pan;
        let to_screen = |p: GP| origin + vec2(p.x as f32 * s, p.y as f32 * s);
        let to_world = |q: Pos2| ((q.x - origin.x) / s, (q.y - origin.y) / s);

        // sheet & grid
        painter.rect_filled(rect, 0.0, Color32::WHITE);
        if self.show_grid && s >= 4.0 {
            let step = if s < 7.0 { 2 } else { 1 };
            let (wx0, wy0) = to_world(rect.min);
            let (wx1, wy1) = to_world(rect.max);
            let dot = Color32::from_rgb(190, 196, 210);
            let mut gx = (wx0.floor() as i32 / step) * step;
            while gx as f32 <= wx1 {
                let mut gy = (wy0.floor() as i32 / step) * step;
                while gy as f32 <= wy1 {
                    let p = to_screen(GP::new(gx, gy));
                    let major = gx % 10 == 0 && gy % 10 == 0;
                    painter.circle_filled(p, if major { 1.3 } else { 0.8 }, dot);
                    gy += step;
                }
                gx += step;
            }
        }

        // ---- hit testing
        let hover = resp.hover_pos();
        let mw = hover.map(to_world);
        let snapped = mw.map(|(x, y)| GP::new(x.round() as i32, y.round() as i32));
        let mut hover_pin: Option<GP> = None;
        let mut hover_comp: Option<u64> = None;
        let mut hover_wire: Option<u64> = None;
        if let Some((x, y)) = mw {
            let mut best = 0.65f32;
            for c in &self.circuit.components {
                for p in c.pin_positions() {
                    let d = ((p.x as f32 - x).powi(2) + (p.y as f32 - y).powi(2)).sqrt();
                    if d < best {
                        best = d;
                        hover_pin = Some(p);
                    }
                }
            }
            for c in self.circuit.components.iter().rev() {
                let (x0, y0, x1, y1) = c.kind.bounds();
                let inv = (4 - c.rot % 4) % 4;
                let (lx, ly) = rotate_f(x - c.pos.x as f32, y - c.pos.y as f32, inv);
                let m = 0.3;
                if lx >= x0 - m && lx <= x1 + m && ly >= y0 - m && ly <= y1 + m {
                    hover_comp = Some(c.id);
                    break;
                }
            }
            if hover_comp.is_none() {
                'outer: for w in self.circuit.wires.iter().rev() {
                    for k in 1..w.points.len() {
                        if seg_dist((x, y), w.points[k - 1], w.points[k]) < 0.5 {
                            hover_wire = Some(w.id);
                            break 'outer;
                        }
                    }
                }
            }
        }
        if self.tool == Tool::Select && self.wiring.is_none() && hover_pin.is_some() && matches!(self.drag, Drag::None) {
            ui.ctx().set_cursor_icon(egui::CursorIcon::Crosshair);
        }

        // ---- input
        let (pressed, released, down, shift, ptr) =
            ui.input(|i| (i.pointer.primary_pressed(), i.pointer.primary_released(), i.pointer.primary_down(), i.modifiers.shift, i.pointer.interact_pos()));
        let dbl = resp.double_clicked();
        if pressed && resp.hovered() {
            if let Some(sp) = snapped {
                self.on_press(sp, hover_pin, hover_comp, hover_wire, shift, ptr.unwrap_or(rect.center()));
            }
        }
        if down {
            let comps = self.selected_comps();
            let wires = self.selected_wires();
            if let (Drag::Move { start, delta, orig }, Some(sp)) = (&mut self.drag, snapped) {
                let d = sp.sub(*start);
                if d != *delta {
                    *delta = d;
                    let mut c = orig.clone();
                    for comp in c.components.iter_mut() {
                        if comps.contains(&comp.id) {
                            comp.pos = comp.pos.add(d);
                        }
                    }
                    reroute(orig, &mut c, &comps, Some(d), &wires);
                    self.circuit = c;
                }
            }
        }
        if released {
            match std::mem::replace(&mut self.drag, Drag::None) {
                Drag::Move { delta, orig, .. } => {
                    if delta != GP::new(0, 0) {
                        self.push_undo(orig);
                        self.edit_stop();
                    }
                }
                Drag::Band { start } => {
                    if let Some(end) = ptr {
                        let r = Rect::from_two_pos(start, end);
                        if r.width() > 3.0 || r.height() > 3.0 {
                            for c in &self.circuit.components {
                                if r.contains(Self::comp_screen_rect(c, origin, s).center()) {
                                    self.selection.insert(Sel::Comp(c.id));
                                }
                            }
                            for w in &self.circuit.wires {
                                if w.points.iter().all(|p| r.contains(to_screen(*p))) {
                                    self.selection.insert(Sel::Wire(w.id));
                                }
                            }
                        }
                    }
                }
                Drag::None => {}
            }
        }
        if dbl {
            if self.wiring.is_some() {
                self.finish_wire();
            } else if let Some(id) = hover_comp {
                self.open_props(id);
            } else if let Some(id) = hover_wire {
                self.wire_props = Some(id);
            }
        }
        if resp.secondary_clicked() && self.wiring.is_some() {
            self.wiring = None;
        }

        // hover info (net voltage under the pointer while simulating)
        self.hover_info.clear();
        if let Some(sim) = &self.sim {
            let net = if let Some(p) = hover_pin {
                self.circuit
                    .components
                    .iter()
                    .enumerate()
                    .find_map(|(ci, c)| c.pin_positions().iter().position(|q| *q == p).and_then(|k| sim.nl.comp_nets.get(ci).map(|v| v[k])))
            } else if let Some(wid) = hover_wire {
                self.circuit.wires.iter().position(|w| w.id == wid).and_then(|i| sim.nl.wire_nets.get(i).copied()).filter(|n| *n != usize::MAX)
            } else {
                None
            };
            if let Some(n) = net {
                self.hover_info = format!("Net {}: {}", n, fmt_reading(sim.v(n), "V"));
            }
        }

        // ---- draw wires
        let sel_w = self.selected_wires();
        let wire_w = (0.16 * s).clamp(1.0, 4.0);
        let net_of_wire: Option<&Vec<usize>> = self.sim.as_ref().map(|s| &s.nl.wire_nets);
        for (wi, w) in self.circuit.wires.iter().enumerate() {
            let [r, g, b] = w.color.rgb();
            let col = if sel_w.contains(&w.id) { SELECT } else { Color32::from_rgb(r, g, b) };
            let pts: Vec<Pos2> = w.points.iter().map(|p| to_screen(*p)).collect();
            if sel_w.contains(&w.id) {
                painter.add(Shape::line(pts.clone(), Stroke::new(wire_w + 3.0, Color32::from_rgba_unmultiplied(0, 140, 255, 60))));
            }
            if hover_wire == Some(w.id) && self.tool == Tool::Select {
                painter.add(Shape::line(pts.clone(), Stroke::new(wire_w + 2.0, Color32::from_rgba_unmultiplied(0, 0, 0, 30))));
            }
            painter.add(Shape::line(pts, Stroke::new(wire_w, col)));
            if self.show_nets && w.points.len() >= 2 {
                let label = net_of_wire.and_then(|v| v.get(wi).copied()).filter(|n| *n != usize::MAX).map(|n| n.to_string());
                if let Some(label) = label {
                    let a = to_screen(w.points[0]);
                    let b = to_screen(w.points[1]);
                    let m = pos2((a.x + b.x) / 2.0, (a.y + b.y) / 2.0);
                    painter.text(m + vec2(2.0, -2.0), Align2::LEFT_BOTTOM, label, FontId::proportional((0.9 * s).clamp(8.0, 18.0)), Color32::from_rgb(0, 120, 0));
                }
            }
        }
        for p in junctions(&self.circuit) {
            painter.circle_filled(to_screen(p), (0.3 * s).clamp(2.0, 6.0), Color32::from_rgb(200, 30, 30));
        }

        // ---- draw components
        let sel_c = self.selected_comps();
        let stroke_w = (0.13 * s).clamp(1.0, 3.0);
        let empty = Live::default();
        for c in &self.circuit.components {
            let selected = sel_c.contains(&c.id);
            let o = to_screen(c.pos);
            let pen = Pen { painter: &painter, origin: o, s, rot: c.rot, stroke: Stroke::new(stroke_w, if selected { SELECT } else { INK }) };
            let live = self.live.get(&c.id).unwrap_or(&empty);
            draw::draw_symbol(&pen, c.kind, &c.params, live);
            draw::draw_labels(&painter, c, o, s);
            if selected {
                let r = Self::comp_screen_rect(c, origin, s).expand(3.0);
                dashed_rect(&painter, r, SELECT);
            } else if hover_comp == Some(c.id) && self.tool == Tool::Select && hover_pin.is_none() {
                let r = Self::comp_screen_rect(c, origin, s).expand(3.0);
                painter.rect_stroke(r, 2.0, Stroke::new(1.0, Color32::from_rgba_unmultiplied(0, 140, 255, 90)));
            }
        }
        if let Some(p) = hover_pin {
            if matches!(self.drag, Drag::None) {
                painter.circle_stroke(to_screen(p), (0.45 * s).max(4.0), Stroke::new(1.5, Color32::from_rgb(230, 40, 40)));
            }
        }

        // ---- previews
        if let (Tool::Place(kind), Some(sp)) = (self.tool, snapped) {
            if resp.hovered() {
                let pen = Pen { painter: &painter, origin: to_screen(sp), s, rot: self.place_rot, stroke: Stroke::new(stroke_w, Color32::from_rgba_unmultiplied(28, 32, 110, 120)) };
                draw::draw_symbol(&pen, kind, &kind.default_params(), &empty);
            }
        }
        if let Some(pts) = &self.wiring {
            let target = hover_pin.or(snapped).unwrap_or(*pts.last().unwrap());
            let mut all = pts.clone();
            let last = *all.last().unwrap();
            if last.x != target.x && last.y != target.y {
                all.push(GP::new(target.x, last.y));
            }
            all.push(target);
            let v: Vec<Pos2> = all.iter().map(|p| to_screen(*p)).collect();
            painter.add(Shape::line(v, Stroke::new(wire_w, Color32::from_rgba_unmultiplied(210, 30, 30, 170))));
            painter.circle_filled(to_screen(target), 3.0, Color32::from_rgb(210, 30, 30));
        }
        if let (Drag::Band { start }, Some(p)) = (&self.drag, ptr) {
            let r = Rect::from_two_pos(*start, p);
            painter.rect(r, 0.0, Color32::from_rgba_unmultiplied(0, 140, 255, 25), Stroke::new(1.0, SELECT));
        }

        // title block in the corner of the sheet
        let title = if self.circuit.title.is_empty() { "Untitled" } else { &self.circuit.title };
        let tb = Rect::from_min_size(rect.right_bottom() - vec2(240.0, 46.0), vec2(232.0, 38.0));
        painter.rect(tb, 0.0, Color32::from_rgba_unmultiplied(255, 255, 255, 230), Stroke::new(1.0, Color32::from_gray(150)));
        painter.text(tb.left_top() + vec2(6.0, 4.0), Align2::LEFT_TOP, title, FontId::proportional(13.0), Color32::from_gray(30));
        painter.text(
            tb.left_bottom() + vec2(6.0, -4.0),
            Align2::LEFT_BOTTOM,
            format!("{} parts · {} wires · zoom {:.0}%", self.circuit.components.len(), self.circuit.wires.len(), self.zoom * 100.0 / 1.6),
            FontId::proportional(11.0),
            Color32::from_gray(90),
        );
        if self.running {
            let badge = Rect::from_min_size(rect.left_top() + vec2(8.0, 8.0), vec2(150.0, 22.0));
            let col = if self.paused { Color32::from_rgb(220, 160, 0) } else { Color32::from_rgb(30, 160, 60) };
            painter.rect_filled(badge, 4.0, col);
            painter.text(badge.center(), Align2::CENTER_CENTER, if self.paused { "SIMULATION PAUSED" } else { "SIMULATING" }, FontId::proportional(12.0), Color32::WHITE);
        }
    }

    fn on_press(&mut self, sp: GP, hover_pin: Option<GP>, hover_comp: Option<u64>, hover_wire: Option<u64>, shift: bool, ptr: Pos2) {
        if let Tool::Place(kind) = self.tool {
            self.edit_stop();
            self.checkpoint();
            let id = self.circuit.add(kind, sp, self.place_rot);
            self.selection.clear();
            self.selection.insert(Sel::Comp(id));
            if !shift {
                self.tool = Tool::Select;
            }
            return;
        }
        if let Some(pts) = &mut self.wiring {
            let target = hover_pin.unwrap_or(sp);
            let last = *pts.last().unwrap();
            if target == last {
                return;
            }
            if last.x != target.x && last.y != target.y {
                pts.push(GP::new(target.x, last.y));
            }
            pts.push(target);
            let start = pts[0];
            let ends_on_wire = self.circuit.wires.iter().any(|w| w.points.windows(2).any(|s| sim::on_segment(target, s[0], s[1])));
            let ends_on_pin = hover_pin.is_some() && target != start;
            if ends_on_pin || ends_on_wire {
                self.finish_wire();
            }
            return;
        }
        if self.tool == Tool::Wire {
            self.wiring = Some(vec![hover_pin.unwrap_or(sp)]);
            return;
        }
        if let Some(p) = hover_pin {
            self.wiring = Some(vec![p]);
            return;
        }
        if let Some(id) = hover_comp {
            if self.running {
                if let Some(c) = self.circuit.comp_mut(id) {
                    if c.kind == Kind::Switch {
                        c.params.closed = !c.params.closed;
                    }
                }
            }
            self.select_click(Sel::Comp(id), shift, sp);
            return;
        }
        if let Some(id) = hover_wire {
            self.select_click(Sel::Wire(id), shift, sp);
            return;
        }
        if !shift {
            self.selection.clear();
        }
        self.drag = Drag::Band { start: ptr };
    }

    fn select_click(&mut self, s: Sel, shift: bool, sp: GP) {
        if shift {
            if !self.selection.remove(&s) {
                self.selection.insert(s);
            }
        } else if !self.selection.contains(&s) {
            self.selection.clear();
            self.selection.insert(s);
        }
        self.drag = Drag::Move { start: sp, delta: GP::new(0, 0), orig: self.circuit.clone() };
    }

    pub(super) fn finish_wire(&mut self) {
        if let Some(pts) = self.wiring.take() {
            let pts = simplify(pts);
            if pts.len() >= 2 {
                self.edit_stop();
                self.checkpoint();
                self.circuit.add_wire(pts);
                self.selection.clear();
            }
        }
    }

    pub(super) fn open_props(&mut self, id: u64) {
        if let Some(c) = self.circuit.comp(id) {
            if c.kind.is_instrument() {
                if !self.open_inst.contains(&id) {
                    self.open_inst.push(id);
                }
            } else if c.kind != Kind::Ground {
                self.props = Some(id);
                self.props_orig = Some(self.circuit.clone());
            }
        }
    }
