const GRID: f32 = 10.0;
const FILE_EXT: &str = "cbs";

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
enum Sel {
    Comp(u64),
    Wire(u64),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Tool {
    Select,
    Wire,
    Place(Kind),
}

enum Drag {
    None,
    Move { start: GP, delta: GP, orig: Circuit },
    Band { start: Pos2 },
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum BottomTab {
    Results,
    Nets,
    Components,
    Erc,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AnalysisKind {
    Interactive,
    DcOp,
    Ac,
    Transient,
    DcSweep,
}

struct AnalysisCfg {
    sel: AnalysisKind,
    ac_fstart: f64,
    ac_fstop: f64,
    ac_ppd: usize,
    tr_stop: f64,
    tr_step: f64,
    tr_use_op: bool,
    dc_src: Option<u64>,
    dc_start: f64,
    dc_stop: f64,
    dc_incr: f64,
    out_vars: HashSet<String>,
    max_step: f64,
    ic_op: bool,
}

impl Default for AnalysisCfg {
    fn default() -> Self {
        AnalysisCfg {
            sel: AnalysisKind::Transient,
            ac_fstart: 1.0,
            ac_fstop: 10e6,
            ac_ppd: 20,
            tr_stop: 5e-3,
            tr_step: 5e-6,
            tr_use_op: false,
            dc_src: None,
            dc_start: 0.0,
            dc_stop: 10.0,
            dc_incr: 0.1,
            out_vars: HashSet::new(),
            max_step: 0.0,
            ic_op: false,
        }
    }
}

enum GraphTab {
    Op { title: String, rows: Vec<(String, f64, &'static str)> },
    Xy { title: String, xlabel: String, xunit: &'static str, series: Vec<sim::Series> },
    Ac { title: String, series: Vec<sim::AcSeries> },
}

impl GraphTab {
    fn title(&self) -> &str {
        match self {
            GraphTab::Op { title, .. } | GraphTab::Xy { title, .. } | GraphTab::Ac { title, .. } => title,
        }
    }
}

struct FileDlg {
    save: bool,
    netlist: bool,
    dir: PathBuf,
    name: String,
    err: Option<String>,
}

