pub enum Kind {
    Resistor,
    Capacitor,
    Inductor,
    Potentiometer,
    DcVoltage,
    DcCurrent,
    AcVoltage,
    Ground,
    Diode,
    Zener,
    Led,
    Switch,
    Lamp,
    Voltmeter,
    Ammeter,
    Probe,
    Multimeter,
    FuncGen,
    Oscilloscope,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Wave {
    Sine,
    Triangle,
    Square,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum MeterMode {
    Volts,
    Amps,
    Ohms,
    Decibel,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum LedColor {
    Red,
    Green,
    Yellow,
    Blue,
    White,
}

impl LedColor {
    pub fn forward_voltage(self) -> f64 {
        match self {
            LedColor::Red => 1.8,
            LedColor::Yellow => 2.0,
            LedColor::Green => 2.1,
            LedColor::Blue => 3.0,
            LedColor::White => 3.1,
        }
    }
    pub fn rgb(self) -> [u8; 3] {
        match self {
            LedColor::Red => [255, 40, 30],
            LedColor::Yellow => [255, 220, 0],
            LedColor::Green => [40, 230, 60],
            LedColor::Blue => [40, 110, 255],
            LedColor::White => [250, 250, 250],
        }
    }
    pub const ALL: [LedColor; 5] = [
        LedColor::Red,
        LedColor::Green,
        LedColor::Yellow,
        LedColor::Blue,
        LedColor::White,
    ];
    pub fn name(self) -> &'static str {
        match self {
            LedColor::Red => "Red",
            LedColor::Green => "Green",
            LedColor::Yellow => "Yellow",
            LedColor::Blue => "Blue",
            LedColor::White => "White",
        }
    }
}

/// Every adjustable value of a part. Unused fields are ignored by a kind.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Params {
    /// Main value: ohms, farads, henries, volts, amps, Zener voltage, lamp volts.
    pub value: f64,
    /// Frequency (AC source, function generator).
    pub freq: f64,
    /// Phase in degrees (AC source).
    pub phase: f64,
    /// DC offset (AC source, function generator).
    pub offset: f64,
    /// Duty cycle in % (function generator square).
    pub duty: f64,
    /// Lamp rated power (W).
    pub power: f64,
    /// Potentiometer setting 0..100 %.
    pub setting: f64,
    /// Potentiometer increment %.
    pub increment: f64,
    /// Interactive key for switches / potentiometers.
    pub key: char,
    /// Switch closed state.
    pub closed: bool,
    pub wave: Wave,
    pub meter: MeterMode,
    /// AC (true) or DC (false) reading for meters.
    pub ac: bool,
    pub led: LedColor,
    /// Diode saturation current.
    pub is: f64,
    /// Diode emission coefficient.
    pub n: f64,
    /// Initial capacitor voltage / inductor current.
    pub ic: f64,
}

impl Default for Params {
    fn default() -> Self {
        Params {
            value: 1.0,
            freq: 1000.0,
            phase: 0.0,
            offset: 0.0,
            duty: 50.0,
            power: 1.0,
            setting: 50.0,
            increment: 5.0,
            key: 'A',
            closed: true,
            wave: Wave::Sine,
            meter: MeterMode::Volts,
            ac: false,
            led: LedColor::Red,
            is: 2.52e-9,
            n: 1.752,
            ic: 0.0,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Component {
    pub id: u64,
    pub kind: Kind,
    pub refdes: String,
    pub pos: GP,
    /// Rotation in quarter turns, clockwise.
    pub rot: u8,
    pub params: Params,
}

