    let prefix = kind.prefix();
    let mut max = 0;
    for p in &b.parts {
        if let Some(rest) = p.comp.refdes.strip_prefix(prefix) {
            if let Ok(n) = rest.parse::<u32>() {
                max = max.max(n);
            }
        }
    }
