s+='''
/// Window / taskbar icon drawn in code: a blue tile with a resistor zigzag and a glowing LED dot.
fn app_icon() -> egui::IconData {
    let n = 64usize;
    let mut rgba = vec![0u8; n * n * 4];
    let zig = |x: f32| -> f32 {
        // zigzag between x = 14..50, flat leads outside
        if !(14.0..=50.0).contains(&x) {
            return 34.0;
        }
        let t = (x - 14.0) / 6.0;
        let f = t.fract();
        let up = (t as i32) % 2 == 0;
        let v = if up { f } else { 1.0 - f };
        26.0 + 16.0 * v
    };
    for y in 0..n {
        for x in 0..n {
            let (fx, fy) = (x as f32 + 0.5, y as f32 + 0.5);
            // rounded square mask
            let r = 12.0;
            let dx = (fx - 32.0).abs() - (32.0 - r);
            let dy = (fy - 32.0).abs() - (32.0 - r);
            let outside = dx.max(0.0).hypot(dy.max(0.0)) - r;
            let a = (0.5 - outside).clamp(0.0, 1.0);
            let shade = 1.0 - fy / 64.0 * 0.35;
            let mut c = [(52.0 * shade) as u8, (110.0 * shade) as u8, (235.0 * shade) as u8];
            // white zigzag line
            if (fy - zig(fx)).abs() < 2.4 && (4.0..=60.0).contains(&fx) {
                c = [255, 255, 255];
            }
            // amber LED dot
            if (fx - 48.0).hypot(fy - 14.0) < 6.0 {
                c = [255, 200, 40];
            }
            let i = (y * n + x) * 4;
            rgba[i..i + 4].copy_from_slice(&[c[0], c[1], c[2], (a * 255.0) as u8]);
        }
    }
    egui::IconData { rgba, width: n as u32, height: n as u32 }
}
'''
open(p,'w').write(s)
EOF
cat > build-windows.bat <<'EOF'
@echo off
rem Builds Circuit Bench for Windows and puts CircuitBench.exe in the "dist" folder.
rem Needs Rust: install it once from https://rustup.rs (choose the default options).
where cargo >nul 2>nul
if errorlevel 1 (
  echo Rust is not installed. Get it from https://rustup.rs and run this script again.
  pause
  exit /b 1
)
cd /d "%~dp0"
cargo build --release
if errorlevel 1 (
  echo The build failed - see the messages above.
  pause
  exit /b 1
)
if not exist dist mkdir dist
copy /y target\release\circuit_bench.exe dist\CircuitBench.exe >nul
echo Done! Double-click dist\CircuitBench.exe to start Circuit Bench.
pause
EOF
cat > README.md <<'EOF'
# Circuit Bench

A circuit design and simulation bench: draw schematics or build on a 2D breadboard,
then run them live with meters, an oscilloscope, a Bode plotter and more.

## Windows

1. Install Rust once from https://rustup.rs (default options; it also offers the
   Microsoft C++ build tools it needs — accept them).
2. Double-click `build-windows.bat` in this folder.
3. Start `dist\CircuitBench.exe`.

Settings (theme, grid, animations) are kept in `%USERPROFILE%\.circuit_bench_settings.json`;
circuits are saved as `.cbs` files, by default in your Documents folder.

## macOS and Linux

```
cargo build --release
./target/release/circuit_bench
```

On Linux you may need the usual desktop libraries (for example on Debian/Ubuntu:
`sudo apt install libxkbcommon-dev libgl1-mesa-dev libx11-dev libxcursor-dev libxrandr-dev libxi-dev`).

## Options

- `--example <n>` open a built-in example (0–8)
- `--view breadboard` start on the breadboard
- `--theme <Light|Dark|Midnight|Blueprint|Sepia|Forest>`
- `--screenshot <file.png>` draw a few frames, save a picture and quit
EOF
